-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[13239] = { id = 13239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volatility", description = "Where to begin... well, you must know that as chief engineer of this vessel I have access to all of the intelligence reports - yes, yes, it's true, and I've recently taken a particular interest in the frostwyrms you reported seeing to the south, and I do believe I've developed a plan that just might work against them... now it'll take a little legwork on your part, but essentially, you build a dummy out of armor and coat it with a splash of this solution, then run for cover!\n\n...You still here, {race}?", completion = "Wahooo! I saw them light up all the way from here! I'll just chalk that up as another success and begin bottling this stuff up for the invasion - of course it might need a little more testing as we go if you're at all interested....", objectives = "Chief Engineer Copperclaw wants you to use Copperclaw's Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.\n\nTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13240] = { id = 13240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees Centrifuge Constructs in your Future!", description = "It is into the Oculus floating above Coldarra that you must travel, {name}.\n\nI have foreseen a situation in which you must destroy the centrifuge constructs therein. I can assure you that if you do not first eliminate these magical creations, you and your friends will fail.\n\nThus I have seen, thus you must do.You will be able to choose one of these rewards:", objectives = "Archmage Timear in Dalaran has foreseen that you must destroy 10 Centrifuge Constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13241] = { id = 13241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees Ymirjar Berserkers in your Future!", description = "King Ymiron's champions stand between you and victory in the not-too-distant future.\n\nYou will travel to the fortress known as Utgarde Pinnacle nestled deep within the woods of the Howling Fjord. I cannot stress how important it is that you and your traveling companions deal with the Ymirjar berserkers therein.\n\nFailure to do so may very well doom you, {name}!You will be able to choose one of these rewards:", objectives = "Archmage Timear in Dalaran wants you to slay 7 Ymirjar Berserkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13242] = { id = 13242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkness Stirs", description = "Darkness stirs, {name}. A tragic event has transpired that none but the Timeless One could have foreseen. Soon your people will be gripped by anger and hatred. War is on the horizon.\n\nThe red dragonflight has done all that it can. What happens next is in the hands of the mortal races of Azeroth.\n\nRegrettably, your journey begins with anguish. A father has lost a child today. You must bear the grim news. Gather the armaments of Saurfang and return them to the elder Saurfang.", progress = "<Saurfang's face contorts.>\n\nMy heart... my strength...", completion = "<Saurfang looks to the heavens.>\n\nLike Brox, my son died a hero. Do not mourn him, {name}. For an orc, there could be no better end! No greater honor! At this moment, my heart swells with pride.\n\nI thank you for returning our battle armor. It will be placed upon his pyre at the Ancestral Grounds of Nagrand.\n\nWe must turn our full attention to more pressing matters.", objectives = "Gather Saurfang's Battle Armor from the field of battle and return it to High Overlord Saurfang at Warsong Hold in Borean Tundra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13243] = { id = 13243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees Infinite Agents in your Future!", description = "The timeline is in danger from the Infinite dragonflight. Without your intervention, all of time will unravel!\n\nYou must travel to a point in time known as the Culling of Stratholme within the Caverns of Time.\n\nIt gives me a migraine just to attempt to see into all of the possible pasts, but I do know that it is crucial for you to kill the Infinite agents.\n\nOnly by slaying them will the true past be preserved and the present and future kept from being undone forever!You will be able to choose one of these rewards:", objectives = "Archmage Timear in Dalaran has foreseen that you must slay 4 Infinite Agents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13244] = { id = 13244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees Titanium Vanguards in your Future!", description = "The entirety of Azeroth is in peril. The mad god Loken has it within his power to put an end to everything!\n\nWithin the Terrestrial Watchtower at the Halls of Lightning, the titanium vanguards stand poised to execute Loken's dread will upon countless unknowing victims.\n\nI have looked into the future, {name}. You are the one to see that this does not come to pass!You will be able to choose one of these rewards:", objectives = "Archmage Timear in Dalaran has foreseen that you must slay 7 Titanium Vanguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13245] = { id = 13245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Ingvar the Plunderer", description = "I need you to assemble a group and lead them into Utgarde Keep. Therein, you are to find and slay Ingvar the Plunderer before he can lead his vrykul forces to sack the nearby Alliance and Horde towns.\n\nI require his axe as proof that he has been dealt with. It's not that I don't trust you. It's simply prudent to be certain that the deed has been done.", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Axe of the Plunderer.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13246] = { id = 13246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Keristrasza", description = "Are you familiar with the story of Keristrasza?\n\nHow she was instrumental in the slaying of Saragosa, the mate of Malygos? How, in turn, he took Keristrasza as his consort, freezing her within a block of ice?\n\nWe have become aware that Malygos has been using his magic to break her will. This has driven her insane.\n\n{name}, you must go into the Nexus in Coldarra and put an end to her before she can be fully turned.\n\nThough it saddens me, I must insist that you bring me her heart as proof.", objectives = "Archmage Lan'dalock in Dalaran wants you to return with Keristrasza's Broken Heart.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13247] = { id = 13247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Ley-Guardian Eregos", description = "The Nexus War rages on and we must do something to turn the tide! Are you willing to fly into the heart of the battle, {name}?\n\nLey-Guardian Eregos is the protector of the conduit through which Malygos is funneling the magical power of Azeroth's ley lines. If he can be slain it will be a great blow to the enemy.\n\nPlease bring me one of his ley line tuners so that we might study it.", objectives = "Archmage Lan'dalock in Dalaran wants you to return with a Ley Line Tuner.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13248] = { id = 13248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: King Ymiron", description = "King Ymiron of Utgarde Pinnacle is the favored vrykul of the Lich King. That alone is reason enough to put an end to him.\n\nBut should he blow the horns and call for all of the leaders of the ymirjar and mjordin alike, the vrykul will become a force more powerful than any other within the Scourge!\n\nIt is up to you, {name}, to see to it that this does not come to pass. Bring me the locket from around his neck so that I will know that Ymiron no longer poses a threat.", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Locket of the Deceased Queen.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13249] = { id = 13249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: The Prophet Tharon'ja", description = "Drak'Tharon Keep once stood as a proud bastion of the Drakkari nation. Now it is nothing more than a stepping stone for the Lich King in his fight to put an end to Zul'Drak and steal the powers of the troll gods.\n\nBut if we were to eliminate their leader, the Prophet Tharon'ja, perhaps we could stop the flow of Scourge troll reinforcements. At the very least this would give the Argent Crusade in Zul'Drak one less thing to worry about.\n\nReturn to me with his tiki so I will know the prophet is slain.", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Prophet's Enchanted Tiki.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13250] = { id = 13250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Gal'darah", description = "The Drakkari prophets of Zul'Drak have done the unthinkable: they've slain most of their gods to absorb their powers! The most dangerous of all is the High Prophet of Akali, Gal'darah.\n\nSequestered within the bowels of Gundrak, Gal'darah has absorbed almost all of the mojo from slain Akali and now stands poised to erupt with his followers from the city. If we do not kill him now, we will be awash in a sea of madness and unthinkable power!\n\nHurry, {name}, bring me what's left of Akali's mojo.", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Mojo Remnant of Akali.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13251] = { id = 13251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Mal'Ganis", description = "{name}, a friend within the bronze dragonflight has given me information that we must exploit.\n\nThe mysterious beings of the Burning Legion called the dreadlords are also known racially as the Nathrezim. Little is known of their homeworld and even that is rumor.\n\nHowever, it is known that Mal'Ganis of the past has made a critical error: he left behind an artifact from his homeworld!\n\nThrough the Caverns of Time, you must travel back to the time known as the Culling of Stratholme. Recover the artifact.", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Artifact from the Nathrezim Homeworld.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13252] = { id = 13252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Sjonnir The Ironshaper", description = "Little is understood about the condition known as the Curse of Flesh. However, there is information to be had within the Halls of Stone.\n\nSjonnir The Ironshaper seems to know a great deal with regard to the curse. We have it on good authority that he is carrying a Titan disc of information upon him that could answer all of our questions.\n\nRetrieve this disc for me, {name}, so that we may learn.", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Curse of Flesh Disc.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13253] = { id = 13253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Loken", description = "Within the Halls of Lightning, Loken is poised to put an end to our world. Need I say more, {name}?\n\nHe sits there listening to the mad whisperings of the Old God trapped beneath Northrend. You and your friends must travel to the Storm Peaks immediately!\n\nConfront Loken within the Terrestrial Watchtower and stop him before it is too late! Bring me his ruby ring so that I will know we are safe once more.", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Celestial Ruby Ring.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13254] = { id = 13254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Anub'arak", description = "The Scourged nerubians are a plague upon our forces.\n\nWhile we are safe from them here, floating above the world, when we set foot upon the land below, it is always with the thought that the undead nerubians could burrow up from the depths of Azjol-Nerub and attack.\n\nIt's in the best interests of everyone if they are thrown into a state of disarray. Kill their former king, and major-domo to the Lich King, the crypt lord, Anub'arak.\n\nPlease bring me his crown... not that he wears it any longer.", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Idle Crown of Anub'arak.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13255] = { id = 13255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Herald Volazj", description = "The nerubians of Ahn'kahet dug too deep during their attempt to escape the invasion of the Scourge. They got too close to the Old God under Northrend.\n\nRousing its awareness, the Old God sent its insane creatures against them, and the nerubians were caught between the proverbial rock and a hard place.\n\nThe leader of the Old Gods' forces, Herald Volazj is one of the nightmarish beings known as The Faceless. Put an end to him and bring me his withered brain.\n\nJust please, try to keep your sanity.", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Faceless One's Withered Brain.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13256] = { id = 13256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Cyanigosa", description = "We're being invaded! The blue dragonflight has teleported into the Violet Hold and they're planning on breaking out from there into the rest of Dalaran!\n\nThere have already been reports of prisoners inadvertently being freed by their actions. It wouldn't surprise me if they're purposefully letting some of them free.\n\n{name}, can you assemble your team quickly and get in there? Cyanigosa is the leader of their invasion force. Bring me her head!", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Head of Cyanigosa.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13257] = { id = 13257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herald of War", description = "The Warchief needs you, champion. Orgrimmar is in a state of martial law. All merchants and services have been shut down as the Warchief prepares for an unavoidable conflict.\n\nI cannot tell you much more - not now. Not in this place.\n\nThe Warchief commands that our strongest champions report to his throne room. Go now, {name}! Take the portal back to Orgrimmar and seek out Thrall.", sourceObjective = "Report to Thrall at Grommash Hold in Orgrimmar.", completion = "The demon lord, Varimathras, and the Forsaken's chief apothecary, Putress, are responsible for this betrayal.\n\n<Thrall nods.>\n\nYes, the same Putress responsible for discovering the cure for the recent Scourge plague outbreak.\n\nThose that would not side with their regime have been executed or banished. Sylvanas was nearly killed in the coup.\n\nThe Horde has lost the Undercity. Orgrimmar will take on the Forsaken refugees until there is a resolution to this crisis. For now we are under martial law.", sourceObjectiveStatus = "unverified-source-field" }
quests[13258] = { id = 13258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opportunity", description = "We recently came upon schematics that indicate a weakness in Icecrown Citadel.  An opening in its defenses, both figuratively and literally.\n\nThe captured diagrams show an orifice leading several hundred feet into the ground.  We're unsure of its purpose, but our scouting has revealed it to be of high importance to the Scourge.\n\nSpeak to Sergeant Kregga below Icecrown Citadel, she's leading the attack on the site.", completion = "Just in time, {name}.  Koltira spoke highly of you.  Perhaps you'll be able to push the scales in our favor.", objectives = "Speak to Sergeant Kregga below Icecrown Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13259] = { id = 13259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Establishing Superiority", description = "We've one shot at dealing some damage to this place -- let's make sure we get it right.\n\nWe've acquired potent, Scourge-made, saronite bombs.  But we must secure this area before we can set them off.\n\nWe're going to need to get the Scourge defenses under control quickly, before reinforcements arrive.\n\nHelp my men out and come back when you're ready for some fireworks.", completion = "You made quick work of the Scourge, {name}.  Let's finish what we came to do here.", objectives = "Sergeant Kregga at Icecrown Citadel wants you to slay 10 Hulking Horrors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13260] = { id = 13260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Takes One to Know One", description = "While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.", completion = "<Koltira looks you up and down.>\n\nI hope for your sake that you're up to this, {class}.", objectives = "Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13261] = { id = 13261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volatility", description = "Wahooo! It works! Not that I had any doubts in my supernatural ingenuity, only that I wasn't quite sure what kind of explosion to expect - let's just say I'm glad to see that you didn't get your eyebrows singed off. So now I just need to show ol' Korm how ya thaw out one 'a them wyrms. He'll hafta promote me to... to... to whatever comes after Chief Engineer! Here, you take another batch of the stuff and head back out to the front and I'll go get Korm...\n\nWell? Move out!", completion = "No good!\n\nKorm kept telling me he was too busy and when I finally got him to come topside and have a look, you had already used the last of the oil. Now he's ticked at me and won't even allow me in his presence again until tomorrow...\n\nCome back then and we'll try again!", objectives = "Chief Engineer Copperclaw wants you to use Copperclaw's Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.\n\nTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13262] = { id = 13262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blow it Up!", description = "This is probably as under-control as this situation is going to get.  Let's do this, {name}.\n\nI need someone to light the fuse on those bombs and it looks like you're the one to do it.", completion = "These bombs look pretty potent.  They should at least put a dent in the surrounding structure.", objectives = "Go to the nearby Saronite Bomb Stack to light the fuse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13263] = { id = 13263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Short Fuse", description = "As you light the fuse, you notice that it is consumed by fire far quicker than you would expect.\n\nThe bombs are about to go off and your best chance at surviving is to lean towards the pit and hope the fall doesn't kill you.", completion = "This pulsing object is covered in a thick layer of ice.  It shimmers strangely beneath the water.", objectives = "Look for clues wherever the fall takes you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13264] = { id = 13264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Abominable!", description = "Abominations...\n\nThey can be a very capable enemy. I've seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.\n\nThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.\n\nFortunately for you, I know these secrets.\n\nThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.", completion = "You see, {class}?\n\nIngenuity can sometimes even the odds against a seemingly overwhelming enemy.", objectives = "Koltira Deathweaver on Orgrim's Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13265] = { id = 13265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "The cut of your clothes suggests to me that you are a Tailor yourself and could easily learn the skill that I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you know the knack of doing it.\n\nFor a small fee I can teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", completion = "Turn that extra cloth you find into something that looks marvelous!" }
quests[13266] = { id = 13266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Life Without Regret", description = "On the day of my death I wish to be able to say that I lived a life without regret. Those who mourn my passing will know that I was a Warchief who made decisions that best served his people.\n\nBut this betrayal by Varimathras and Putress... All that we have worked for is for nothing.\n\n<Thrall's chest heaves with a heavy sigh.>\n\nJustice must be served.\n\nPortals to Undercity will be active momentarily. Vol'jin will be waiting for you. I will meet you there soon. Together we will make it right, {name}.", sourceObjective = "Take the portal to Undercity located in Grommash Hold and report to Vol'jin.", completion = "Let me get you up to speed, {name}.\n\nUndercity is a war-zone. Putress' apothecaries and Varimathras' demons have seized control. They've taken a defensive position inside and are using that damned blight against our troops.", sourceObjectiveStatus = "unverified-source-field" }
quests[13267] = { id = 13267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle For The Undercity", description = "The entirety of the Undercity is controlled by Varimathras. Our soldiers stand ready, waiting for the Warchief to give the attack orders.\n\nHelp the Horde take back the Undercity and earn your place among our greatest champions! Should you survive the assault, report to Thrall.\n\nCheck in with the Warchief when you are ready to begin.", sourceObjective = "Assist Thrall and Sylvanas in retaking the Undercity for the Horde.\n\nReport to Thrall should you succeed.", completion = "Tomorrow brings with it uncertainty. Gone are the days of Alliance and Horde battling alongside each other in pursuit of a common enemy. A new battle dawns, {name} - a battle in which there can be no victor.\n\nBut we must continue our march towards Icecrown. We have no choice in that matter. Our salvation lies with heroes like you, {name}. The future of the Horde - of the world - depends on you.\n\nLet us return to Orgrimmar. You must return to Northrend at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[13268] = { id = 13268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "You look like someone who knows their way around a needle and thread so maybe I can help you.\n\nThe northern humanoids wear clothes that can quickly be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", completion = "Come back when you have the skill and I can provide all of your tailoring training." }
quests[13269] = { id = 13269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "The humanoids of the northern lands wear garments that can be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional frostweave cloth from the humanoids of Northrend that you slay.", completion = "May you slay many humanoids and take their cloth." }
quests[13270] = { id = 13270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "You be looking like da type who be knowin' how to sew some threads and so I got somethin' for ya.\n\nDa humanoids of da north be wearin' tings dat can be changed into cloth if you be knowin' da trick of it.\n\nIf you been willin' to part with some cash I can teach you da skill of Cloth Scavenging that be givin' ya extra frostweave cloth from the humanoids of Northrend.", completion = "I be appreciatin' your business." }
quests[13271] = { id = 13271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Voice in the Dark", description = "The object is not a crystal at all, but some form of organ, encased in ice.\n\nAs you touch it, your hand reels in horrible pain.  You feel as if your hand has been cut, yet there is no visible wound.\n\nAs you collect your thoughts, you hear a young boy's voice nearby.\n\n\"You really shouldn't have done that.\"", completion = "I saw him get rid of it, you know?  He threw it all the way down here.\n\nSaid he wouldn't need it anymore.  Said it made him weak.", objectives = "Investigate the nearby voice in Naz'anak, the Forgotten Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13272] = { id = 13272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "As a Tailor I think you are ready to learn what I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you have the proper skill.\n\nFor a couple of gold coins I can teach you the skill of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", completion = "I think you will find this skill helps you a great deal on your path to tailoring greatness!" }
quests[13273] = { id = 13273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going After the Core", description = "With Norgannon's Shell in hand, only half of the archive key remains to be found. Luckily, I've had the Explorers' League hard at work chasing down leads about the whereabouts of Norgannon's Core.\n\nFar to the southeast of the Inventor's Library, on the slopes to the north of Dun Niffelem, is a camp bearing my name. The Explorers' League representatives seeking the second half of the key are based there. Bring me the maps and the notes they've made and we should be able to track down the other key half.", progress = "Have you recovered those notes?", completion = "Ruined? What d'you mean, the camp's been ruined?\n\n<Brann clenches his fists in anger.>\n\nThose iron dwarves will pay for this! There's little we can do now, and we have to focus on finishing the key. But once I get into the halls of Ulduar, the irons and their masters will answer for what they've done!", objectives = "Find Prospector Khrona's Notes and Prospector Soren's Maps at Brann's Base-Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13274] = { id = 13274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Core's Keeper", description = "Prospector Soren's notes say that Norgannon's Core is in the keeping of a sentinel named Athan, one of Mimir's creations.\n\nSoren says the vault where Athan resides is called \"Loken's Bargain\" these days.\n\nLoken, eh? The earthen have mentioned him.\n\nThe vault is said to be southwest of the ruined Explorers' League camp, with a round entrance on a mountainside overlooking the Valley of Ancient Winters.\n\nFind this Athan and get the core from him, but I wouldn't be surprised if you were in for a fight.", progress = "Was Prospector Soren right? Did you finally find Norgannon's Core?", completion = "This is really it! The key is almost within our grasp. All we need now is a way to combine the shell and the core into a single key. Let's see what Prospector Soren had to say about this...", objectives = "Obtain Norgannon's Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13275] = { id = 13275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Hide", description = "You shouldn't have touched it.  But now that you did, he's going to come looking for you.\n\nAnd he'll find you.  Unless you hide yourself from him.\n\nBring me blood from the faceless ones if you want to live!", progress = "Did you get the blood?", completion = "What are you waiting for?  You have to rub it on you!\n\nQuick!  Or he'll see you!", objectives = "Matthias Lehner wants you to obtain 3 Faceless One's Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13276] = { id = 13276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Abominable!", description = "You know what to do, {class}.\n\nTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.\n\nYou would do well to refine this tactic for when we make our assault on the gate.", completion = "I see your skills with the abominations are developing nicely.\n\nBe diligent, friend, and soon the gate will belong to the Horde.", objectives = "Koltira Deathweaver on Orgrim's Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13277] = { id = 13277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Giants", description = "While it's going to be crucial to defeat the Scourge on the ground, we mustn't neglect the gate itself.\n\nThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.\n\nMuster a force and defeat these giants. We need to know just what we're up against in terms of their strength.\n\nOh... and bring me their spines. If memory serves, there's a little trick I can share with you.", progress = "Any success against the giants, {race}?", completion = "Excellent. These look to be usable samples.\n\nTime again to use the enemy's strength against them....", objectives = "Koltira Deathweaver on Orgrim's Hammer wants you to bring him 5 Pustulant Spines from the Pustulant Horrors on Mord'rethar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13278] = { id = 13278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coprous the Defiled", description = "Reports of a powerful zombie at the death gate have reached my ears, {class}.\n\nWe cannot allow a potential threat such as this to go unchallenged. Any information you are able to glean from engaging it will be better than what we know now.\n\nGo to the western chamber of the gate and find this creature. Fight him, and find a weakness we might exploit.", completion = "Well done, {class}.\n\nPerhaps with some investigation, we can discover how they are bringing such a creature into existence.", objectives = "Koltira Deathweaver aboard Orgrim's Hammer wants you to kill Coprous the Defiled at Mord'rethar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13279] = { id = 13279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Chemistry", description = "<Koltira takes the pustulant spines and drains their fluid into a flask.>\n\nA little-known quality of the flesh giants...\n\nTheir spinal fluid interacts with the plague in a very interesting way, turning it into a corrosive acid.\n\nPoured from the towering ramparts, acid may not be a welcome sight to the troops below, but at least the victims won't rise up and add to the enemy's numbers.\n\nPour the contents of this flask into one of the plague cauldrons in the western chamber of the death gate.", completion = "You have done well, {class}.\n\nWhen our armies arrive to march on the Citadel, we will have a solid plan in place for taking the death gate.", objectives = "Koltira Deathweaver aboard Orgrim's Hammer wants you to use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13280] = { id = 13280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Mountain", description = "You've just got to get my jumpbot to the tippy top of the mountain to the northwest here at Ymirheim pronto, {name}!\n\nThat dastardly, no-good Blast Thunderbomb is working on his own bot, and I'm afraid he almost has it completed. We're in a race to see who's gonna be king of the mountain!\n\nOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Alliance, and my engineering skills, are the best!", progress = "Hold on a second... you haven't planted our battle standard yet!\n\nWhat's the hold up?", completion = "YOU DID IT! YOU DID IT!\n\n<Frazzle jumps and gives you a big hug.>\n\nOh, you're just my favorite hero ever!\n\nYou think you could come back again tomorrow?", objectives = "Frazzle Geargrinder in Ymirheim wants you to use her Geargrinder's Jumpbot to plant the Alliance Battle Standard in the skulls at the top of the mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13281] = { id = 13281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neutralizing the Plague", description = "You no longer need my assistance in neutralizing the enemy's plague cauldrons, {race}.\n\nHunt down the flesh giants at the death gate and use the fluid from their spines to render batches of the plague ineffective.\n\nYou are striking at the heart of the enemy's strategy. This is an important mission - vital to our cause, and should be carried out whenever time permits.\n\nRemember, the giants and the plague cauldrons can be found on Mord'rethar.", completion = "One less plague cauldron to account for when the battle commences.\n\nYour commander will be pleased.", objectives = "Koltira Deathweaver aboard Orgrim's Hammer wants you use Pustulant Spinal Fluid on a blight cauldron at Mord'rethar.\n\nYou can create Pustulant Spinal Fluid by using a Giant Spine collected from a Pustulant Horror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13282] = { id = 13282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Surface", description = "You should leave now.  You'll find a portal behind me.  It'll take you to the surface.\n\nWe'll meet again.  He'll be looking for you.\n\nIt's only a matter of time until he finds you.", completion = "{name}!  We thought you were dead!\n\nWe lost a few men in that explosion... but we sure put a hurt on the Scourge.  They're scrambling their forces back to the citadel and leaving big gaps in their defenses.  It's time to push forward.", objectives = "Return to Koltira Deathweaver aboard Orgrim's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13283] = { id = 13283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Mountain", description = "Yo, {name}, I need you to get my jumpbot to the top of this mountain to the southeast, like yesterday!\n\nThat girly, self-righteous Frazzle Geargrinder thinks that her jumpbot's better than mine. Hah! We're in a race to see who's gonna be king of the mountain!\n\nOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Horde, and my mad engineering skills, are the best!", completion = "I knew you were the right {race} for the job!\n\n\n\nI gotta admit that right now you're my favorite {class} of all time!\n\nWhat do you say to a repeat performance again tomorrow? I can make it worth your while!", objectives = "Blast Thunderbomb in Ymirheim wants you to use his Thunderbomb's Jumpbot to plant the Horde Battle Standard in the skulls at the top of the mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13284] = { id = 13284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault by Ground", description = "Greetings {class}.\n\nOur troops have been attempting to storm Ymirheim for some time, but these vrykul are far more vicious than any we've faced before. They've been ambushing us repeatedly as we try to make it up the pass, and we've lost a lot of men.\n\nIf you want to lend yourself to the battle and help get my squad to the gates of Ymirheim safely, we will gladly reward you for your efforts. Once at the gates, we'll dig in and wait for reinforcements to catch up to us.", completion = "You have my thanks.\n\nThis has been a brutal operation, but we haven't had any great options otherwise - they're being equally as unforgiving to our aerial assault. We need to rout these vrykul if we're going to stand any chance of pressing on in Icecrown.\n\nWe're likely to need more help later. Please lend yourself to the battle again should the chance present itself.", objectives = "Escort the Skybreaker troops to the gates of Ymirheim. Return to Ground Commander Koup at the edge of the glacier east of Ymirheim for compensation after the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13285] = { id = 13285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging the Keystone", description = "Aha! Here it is: the Temple of Invention, the seat of Keeper Mimir himself! Of course, that's where one would go to join the two parts of the key.\n\nAccording to the prospector's notes, the Temple of Invention is one of the highest points on the western side of the Terrace of the Makers. That means it should be roughly east of your Grom'arsh Crash Site.\n\nI'll meet you at the temple and we'll combine the parts together.", completion = "<Boktar nods in approval as you tell him how you helped Brann recover the pieces of the keystone and combine them.>\n\nBrann may prove to be just the ally we need to discover what is truly happening in Ulduar. You've done well in aiding him. We need all the help we can get against this Loken and his iron dwarf minions.", objectives = "Brann Bronzebeard wants you to meet him at the Temple of Invention and help him combine Norgannon's Shell and Norgannon's Core. Once you have helped Brann, report back to Boktar Bloodfury at the Grom'arsh Crash-Site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13286] = { id = 13286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...All the Help We Can Get.", description = "Desperate times, {class}...\n\nAs uncomfortable as it makes me, I'm prepared to accept assistance from anyone - including our resident death knight.\n\nGo to Thassarian and see if he can help us develop tactics against the Scourge that will ensure victory once we are able to mount another offensive.\n\nWe have come so far... we must not fail here!", completion = "It was wise of Captain Bartlett to send you.\n\nWhile he frets over your conflict with the Horde, someone must remain exclusively focused on the real mission here - the march on Icecrown Citadel.\n\nWho better to direct your efforts than a former servant of the Lich King?", objectives = "High Captain Justin Bartlett aboard the Skybreaker wants you to speak to Thassarian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13287] = { id = 13287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poke and Prod", description = "As someone of your experience must surely know, there's no better way to familiarize one's self with their enemy than by confronting them in combat.\n\nWhile you no doubt lust for the glory of taking Icecrown Citadel, that cannot happen without taking each of the Lich King's gates first. For now, you must focus your efforts on the first of these...\n\nReturn to the Broken Front. Engage the enemy in battle. Search for a weakness we might exploit and return to me with a detailed report.", completion = "Really, {class}?\n\nNothing notable to report?\n\n\n\nI beg to differ...", objectives = "Thassarian on the Alliance gunship, Skybreaker, wants you to kill 5 Hulking Abominations, 5 Malefic Necromancers, and 5 Shadow Adepts at the Broken Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13288] = { id = 13288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Abominable!", description = "Abominations...\n\nThey can be a very capable enemy. I've seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.\n\nThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.\n\nFortunately for you, I know these secrets.\n\nThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.", completion = "You see, {class}?\n\nIngenuity can sometimes even the odds against a seemingly overwhelming enemy.", objectives = "Thassarian on the Skybreaker wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13289] = { id = 13289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Abominable!", description = "You know what to do, {class}.\n\nTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.\n\nYou would do well to refine this tactic for when we make another assault on the gate.", completion = "I see your skills with the abominations are developing nicely.\n\nBe diligent, friend, and soon the death gate will belong to the Alliance.", objectives = "Thassarian on the Skybreaker wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13290] = { id = 13290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Attention, Please", description = "Chief Engineer Boltwrench has proven invaluable in his service aboard the Stormbreaker. Were it not for his ingenuity, we'd be sprinkled across half of the glacier several times over by now.\n\nThe thing is, he feels he must share his every miniscule invention or discovery - most of which I don't even understand.\n\nMy focus must be squarely on our enemies right now. I cannot afford any distractions.\n\nPlease visit him in my stead, {name}. And if you can, assist him. You'll find him belowdecks.", completion = "Cappy sent you in his place, did he?\n\nVery well, {class}. Roll up those sleeves... time to get to work!", objectives = "High Captain Bartlett wants you to speak with Chief Engineer Boltwrench in the Skybreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13291] = { id = 13291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borrowed Technology", description = "I get it, I get it. Cappy's too busy to see this for himself. His loss!\n\nSee, I've managed to 'acquire' a certain shipment of solution from the enemy. And as much as I hate tinkerin' with inferior goblin technology, I'm inclined to make an exception here.\n\nTake this sample. I'll need you to run a few field tests, just to prove its usefulness, while I try to do a little reverse engineering to duplicate the creation process.\n\nGo to the front and gather the materials to make a decoy, then use the oil.", completion = "Good news!\n\nI've managed to reproduce the solution - hardly an accomplishment, of course.\n\nDoubt I'll live to see the day those neanderthal goblins cook up somethin' a gnome can't recreate in his sleep!", objectives = "Chief Engineer Boltwrench aboard the Skybreaker wants you to use the Smuggled Solution at the Broken Front.\n\nUsing the solution will require an Abandoned Helm, Abandoned Armor, and Pile of Bones, all found at the Broken Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13292] = { id = 13292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Solution Solution", description = "Oh, yes, yes. Back again, are we? Never enough practice, I suppose.\n\nHere we are, the solution to that pesky frostwyrm problem.\n\nMake them scarce, {race}. The more you take out now, the less we face when we are again ready to attempt our march on the citadel.\n\nBest of luck, now. And do bring back whatever you don't use.", completion = "Good show! Good show indeed. You're turning into a regular wyrmslayer!\n\nCome back when you're ready to thin their numbers even further.", objectives = "Chief Engineer Boltwrench aboard the Skybreaker wants you to use the Smuggled Solution at the Broken Front.\n\nUsing the solution will require an Abandoned Helm, Abandoned Armor, and Pile of Bones, all found at the Broken Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13293] = { id = 13293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to Ymirheim!", description = "You need to get down to Ymirheim, that big frost vrykul town in the middle of Icecrown.\n\nOur boy, Blast Thunderbomb, is down there on the west side of town representing the Warsong Offensive in a competition against the Alliance. It's his jumpbot versus theirs in a king of the mountain contest!\n\nDon't let us down, {name}. Goblin engineering pride is on the line! Besides, all the boys here in the hold are counting on you.\n\nThat and we've got money riding on it that you can kick those cowards in the pants!", completion = "Oh man, am I glad to see you! Did the chief send you down from the Hammer?", objectives = "Speak with Blast Thunderbomb in Ymirheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13294] = { id = 13294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Giants", description = "While it's going to be crucial to defeat the Scourge on the ground, we mustn't neglect the gate itself.\n\nThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.\n\nMuster a force and defeat these giants. We need to know just what we're up against in terms of their strength.\n\nOh... and bring me their spines. If memory serves, there's a little trick I can share with you.", progress = "Any success against the giants, {race}?", completion = "Excellent. These look to be usable samples.\n\nTime again to use the enemy's strength against them....", objectives = "Thassarian on the Skybreaker wants you to bring him 5 Pustulant Spines from the Pustulant Horrors on Mord'rethar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13295] = { id = 13295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Chemistry", description = "<Thassarian takes the pustulant spines and drains their fluid into a flask.>\n\nA little-known quality of the flesh giants...\n\nTheir spinal fluid interacts with the plague in a very interesting way, turning it into a corrosive acid.\n\nPoured from the towering ramparts, acid may not be a welcome sight to the troops below, but at least the victims won't rise up and add to the enemy's numbers.\n\nPour the contents of this flask into one of the plague cauldrons in the western chamber of the death gate.", completion = "You have done well, {class}.\n\nWhen our armies arrive to march on the Citadel, we will have a solid plan in place for taking the death gate.", objectives = "Thassarian aboard the Skybreaker wants you to use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13296] = { id = 13296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to Ymirheim!", description = "I need you down in Ymirheim, that big frost vrykul town in the middle of Icecrown.\n\nFrazzle Geargrinder is down there on the south side of town representing the Valiance Expedition in a competition against the Horde scum. It's her jumpbot versus theirs in a king of the mountain contest!\n\nDon't let us down, {name}. Gnomish engineering pride is on the line! Besides, all the boys here in the hold are counting on you.\n\nThat and we've got money riding on it that you can kick those idiots in the pants!", completion = "Did the chief send you down from the Skybreaker? Isn't that thing sweet?!", objectives = "Speak with Frazzle Geargrinder in Ymirheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13297] = { id = 13297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neutralizing the Plague", description = "You no longer need my assistance in neutralizing the enemy's plague cauldrons, {race}.\n\nHunt down the flesh giants at the death gate and use the fluid from their spines to render batches of the plague ineffective.\n\nYou are striking at the heart of the enemy's strategy. This is an important mission - vital to our cause, and should be carried out whenever time permits.\n\nRemember, the giants and the plague cauldrons can be found on Mord'rethar.", completion = "One less plague cauldron to account for when the battle commences.\n\nYour captain will be highly pleased.", objectives = "Thassarian aboard the Skybreaker wants you use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.\n\nYou can create Pustulant Spinal Fluid by using a Giant Spine collected from a Pustulant Horror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13298] = { id = 13298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coprous the Defiled", description = "Reports of a powerful zombie at the death gate have reached my ears, {class}.\n\nWe cannot allow a potential threat such as this to go unchallenged. Any information you are able to glean from engaging it will be better than what we know now.\n\nGo to the western chamber of the gate and find this creature. Fight him, and find a weakness we might exploit.", completion = "Well done, {class}.\n\nPerhaps with some investigation, we can discover how they are bringing such a creature into existence.", objectives = "Thassarian aboard the Skybreaker wants you to kill Coprous the Defiled at Mord'rethar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13299] = { id = 13299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ZZOLDWisp Cloak" }
quests[13300] = { id = 13300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves to Saronite", description = "Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.\n\nI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that's exactly what we will do.\n\nUnfortunately, I've been ordered to stay on this gunship and serve as an ambassador to the Valiance Expedition. Will you please rescue them in my stead, {name}?", completion = "They're being driven insane? Voices in their heads?\n\nVoices in your head?!\n\nI want you to clear your mind of the taint that has crept into that place, boy.\n\nWe'll try to get the remainder of them out of there again tomorrow when you've had a chance to rest.", objectives = "Absalan the Pious aboard the Skybreaker wants you to rescue 10 Saronite Mine Slaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13301] = { id = 13301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault by Ground", description = "Greetings {class}.\n\nOur troops have been attempting to storm Ymirheim for some time, but these vrykul are far more vicious than any we've faced before. They've been ambushing us repeatedly as we try to make it up the pass, and we've lost a lot of men.\n\nIf you want to lend yourself to the battle and help get my squad to the gates of Ymirheim safely, we will gladly reward you for your efforts. Once at the gates, we'll dig in and wait for reinforcements to catch up to us.", completion = "You have my thanks.\n\nThis has been a brutal operation, but we haven't had any great options otherwise - they're being equally as unforgiving to our aerial assault. We need to rout these vrykul if we're going to stand any chance of pressing on in Icecrown.\n\nWe're likely to need more help later. Please lend yourself to the battle again should the chance present itself.", objectives = "Escort the Kor'kron troops to the gates of Ymirheim. Return to Ground Commander Xutjja at the edge of the glacier north of Ymirheim for compensation after the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13302] = { id = 13302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves to Saronite", description = "Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.\n\nI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that's exactly what we will do.\n\nUnfortunately, I've been ordered to stay on this gunship and serve as an ambassador to the Warsong Offensive. Will you please rescue them in my stead, {name}?", completion = "They're being driven insane? Voices in their heads?\n\nVoices in your head?!\n\nI want you to clear your mind of the taint that has crept into that place, boy.\n\nWe'll try to get the remainder of them out of there again tomorrow when you've had a chance to rest.", objectives = "Brother Keltan aboard Orgrim's Hammer wants you to rescue 10 Saronite Mine Slaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13303] = { id = 13303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Panchurian Candidate" }
quests[13304] = { id = 13304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Repairs", description = "The Scourge is still reeling from our attack, {name}.  Now is the time to capitalize on our momentum.\n\nThe strategically important valley below us is wide open.  We've located a disassembled demolisher vehicle in what we believe is working condition in the southeastern corner of the Valley of Lost Hope area.\n\nIf you can get the remaining parts from the Scourge scavengers, you should be able to get it running again.  A single working demolisher can wreak havoc on the enemy's ground units.", progress = "The demolisher has suffered much damage.", completion = "The Demolisher has seen better days, but the structure hasn't suffered any permanent damage.  The parts you obtained should be enough to get it running again, at least temporarily.", objectives = "Koltira Deathweaver aboard Orgrim's Hammer wants you to collect 5 Demolisher Parts from the Scavenging Geists in the Valley of Lost Hope and take them to the Wrecked Demolisher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13305] = { id = 13305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Your Worst", description = "You're going to use this machine against the Scourge?  You're not going to win against them like that.\n\nYou can destroy hundreds... even thousands of them.  But you won't win.  Not out here.\n\nWhen you're done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you're up against.", completion = "You see?  You killed your fair share, but for every one you destroyed, another rose from the dirt to take its place.\n\nYou don't know what you're up against, {name}.  Let me show you.", objectives = "Use the Refurbished Demolisher to destroy 150 Decomposed Ghouls, 20 Frostskull Mages and 2 Bone Giants in the Valley of Lost Hope. Speak to Matthias Lehner at the First Legion Forward Camp when you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13306] = { id = 13306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raise the Barricades", description = "When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.\n\nWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.\n\nTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.", completion = "<Koltira nods curtly.>\n\nGood. It's not much protection, but it's better than nothing. That gate is still the perfect choke point if the Scourge commanders know what they're doing. We must gain control of as much of the surrounding area as possible.", objectives = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to construct 8 Barricades using your Barricade Construction Kit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13307] = { id = 13307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodspattered Banners", description = "In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley's dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.\n\nIt falls to you to rid us of this obstacle, and thin the resistance before the main body can advance.", completion = "You have removed the Scourge banner-bearers and their minions? Good. Our preparations must continue.", objectives = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to kill 5 Scourge Banner-Bearers, 5 Scourge Converters, and 20 Converted Heroes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13308] = { id = 13308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind Tricks", description = "<The creature speaks directly into your mind, its thoughts painful and strange.>\n\n{race}-thing, I am in need of your assistance. Like your enslaved friends, I am a victim of the Lich King's ymirjar and their avarice. When I rose from below to investigate the noises coming from this cavern they captured and chained me.\n\nWill you please help me? The foreman of these mines holds the key to my chains. Kill him!\n\n<You can feel a pushing against your mind as if the creature is trying to coerce you.>", progress = "You will be richly rewarded for your service to me.\n\n<The darkspeaker projects soothing feelings into your mind.>\n\nYou will not regret unfettering me.", completion = "<Another wave of euphoria, mixed with some pain, crashes through your mind as you approach the creature.>\n\nGood... good! So that you know I am being fair, I will first give you your reward as promised.\n\nAnd then you will willingly hand me the key.", objectives = "Darkspeaker R'khem in the Saronite Mines wants you to recover the Foreman's Key to his chains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13309] = { id = 13309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault by Air", description = "I've got some boys suited and ready for their drops inside of Ymirheim. I could use you to see them there safely.\n\nInside the walls, the vrykul have set up some kind of automated spear guns that have been tearing up our transports. We had our engineers install a Suppression Turret to shut down those spear guns - just fire a round near any gun and the smoke should block its sight and clog its gears.\n\nHop on the turret and see to it that all my boys make it to their drops in one piece.", progress = "Did you get my boys inside?", completion = "Excellent work, soldier. We could use more able bodies like you around here - stop by another day if the operation hasn't wrapped up.", objectives = "Ground Commander Koup at the edge of the glacier east of Ymirheim has ordered you to use the Skybreaker Suppression Turret to keep the Skybreaker Troop Transport alive long enough to make all of its drops.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13310] = { id = 13310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault by Air", description = "Alright scrub, I've got something to keep you from being a complete waste.\n\nA unit of highly trained infiltrators is ready to be dropped inside of Ymirheim. The vrykul inside have automated spear guns that have been ripping our transports to shreds, so we had the engineers on Orgrim's Hammer whip us up a suppression turret.\n\nYou're the gunner. Launch rounds at their spear guns to obscure their vision and clog their gears. See to it that my men all make their drops and the transport stays in one piece.", progress = "Get the job done?", completion = "Only partly useless then. Good work.", objectives = "Ground Commander Xutjja at the edge of the glacier north of Ymirheim has ordered you to use the Kor'kron Suppression Turret to keep the Kor'kron Troop Transport alive long enough to make all of its drops.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13311] = { id = 13311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons Deck", description = "Now that you have gathered all of the Demon cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone or something.", progress = "I see that you have managed to complete a deck of Demons!   Congratulations!", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return.", objectives = "Use the Demons Deck to summon a Darkmoon Fortune Teller and give the deck to them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13312] = { id = 13312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ironwall Rampart", description = "The Ironwall Rampart overlooks the Valley of Fallen Heroes, west of Aldur'thar. The rampart dominates the fields below on all sides. We will not be able to advance if the rampart cannot be taken, but it is held by Grimkor the Wicked and his Cult of the Damned disciples.\n\nIf you can weaken Grimkor, our forces know what to expect as we advance. Take this rune of distortion. Unleashing its power near Grimkor's orb at the end of the rampart should be enough to get the necromancer's attention.", completion = "So Grimkor has fallen by your hand? Excellent work. With him out of the way, our chances of taking and holding the rampart during the assault are greatly improved.", objectives = "Defeat Grimkor the Wicked and return to Koltira Deathweaver aboard Orgrim's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13313] = { id = 13313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinding the Eyes in the Sky", description = "The Alliance has somehow managed to field a squadron of recon vehicles over the Valley of Fallen Heroes and Icecrown Glacier, the broad areas west of Aldur'thar.\n\nThey cannot be permitted to take the lead in this fight. Chief Engineer Copperclaw has supplied me with the perfect weapon to deal with this threat -- he calls his new missile the SGM-3. I have his assurances that it will take out the Alliance flying machines in a single hit. Go and use this weapon to give us the upper hand.", completion = "Good. Fewer Alliance pests to stand in our way. We'll show them what true warriors look like.", objectives = "Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13314] = { id = 13314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get the Message", description = "The Horde is up to something and I don't like it. After the stunt they pulled on the Broken Front, they're capable of anything, and it's up to us to stop it.\n\nThere's been a flurry of activity in the skies over the Icecrown Glacier, to the west of Aldur'thar and the Ironwall Rampart. Horde scouts and messengers streak in and out on dragonhawks, carrying reports and orders. Take this dart gun and use it to kill the Orgrim's Hammer Scouts. It'll probably work best if you're flying, too.", progress = "Have you intercepted those dispatches?", completion = "It's good to have someone competent running missions, {name}. If only we had an army of paladins like you, we could show the Horde what we're made of. These captured reports will help us to maintain the upper hand in this fight. We may be down, but we're far from out.", objectives = "Capture 6 Orgrim's Hammer Dispatches from Orgrim's Hammer Scouts and bring them to High Captain Justin Bartlett aboard the Skybreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13315] = { id = 13315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sneak Preview", description = "Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from those Horde you insist on contending with...\n\nAt any rate, our next focus will be the gate of desolation. Fly down and become familiar with it and with the enemies posted there.\n\nWhen you return, I will have your missions prepared.", progress = "Have you scouted the gate of desolation, {class}?", completion = "Well and good, {class}.\n\nNow that you've seen firsthand what we're up against, it's time to get to work...", objectives = "Thassarian, aboard the Skybreaker, wants you to fly down to the gate of desolation, visiting the south, central, north, and northwest regions of the gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13316] = { id = 13316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guardians of Corp'rethar", description = "Corp'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.\n\nWe must weaken its defenses, or our army's strength will break upon its walls.\n\nIts battlements are manned by some of the Lich King's fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.", completion = "I hope your success at Corp'rethar will prove an omen of the battle ahead. The Lich King cannot sit idly by as we march to the very gates of his stronghold.", objectives = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to kill 5 Harbingers of Horror and 5 Corp'rethar Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13318] = { id = 13318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag and Drop", description = "The Cult of the Damned hold the gate of desolation, eh? No surprise there.\n\nTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They're almost certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nKill the fools until you find one, {class}, then use it on a subjugator.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old....", objectives = "Thassarian, aboard the Skybreaker, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13319] = { id = 13319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chain of Command", description = "Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.\n\nWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, {race}, is a worthy enough goal for now.\n\nSeek out these overseers and return to me when they have been dispatched.", completion = "Well done, {race}. But don't break your arm patting yourself on the back. They'll have those overseers replaced in no time...", objectives = "Thassarian aboard the Skybreaker wants you to go to Aldur'thar and defeat Overseer Faedris, Overseer Savryn, Overseer Veraj, and Overseer Jhaeqon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13320] = { id = 13320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannot Reproduce", description = "I smell their cauldrons from here, but that's not plague they're cooking.\n\nPledges to the cult are forced to drink a concoction that steals their will and enslaves them forever to the Lich King.\n\nSome say the potion contains the twisted soul of a being who was tormented before being mercilessly slaughtered, but I've never been able to reproduce it...\n\nFill this flask with a sample from each of the three cauldrons in the northwest region of the gate and bring it to Chief Engineer Boltwrench.", progress = "Whatdya got there, {race}?", completion = "<Boltwrench pours the contents of the flask into his tetrahydroparticle analyzer.>\n\nWhat we have here is a simple failure to conglomerate...", objectives = "Thassarian aboard the Skybreaker wants you to use the Partitioned Flask at each of the 3 Cultists' Cauldrons at Aldur'thar, then bring it to Chief Engineer Boltwrench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13321] = { id = 13321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retest Now", description = "This should do the trick!\n\nThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence once you've defeated them.\n\nWhen you've collected a bunch of them, throw the writhing mass of twisted souls into any of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", completion = "Wahoo!\n\nThat'll teach 'em!", objectives = "Chief Engineer Boltwrench aboard the Skybreaker wants you to throw a Writhing Mass into a cauldron at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13322] = { id = 13322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retest Now", description = "Those twisted cultists are looking for souls to put in their crazy-juice? Then let's help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence.\n\nOnce you've collected a bunch of 'em, throw the writhing mass of twisted souls in one of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", completion = "Wahoo!\n\nThat'll teach 'em!", objectives = "Chief Engineer Boltwrench aboard the Skybreaker wants you to drink the Diluted Cult Tonic, kill any Cultists at Aldur'thar and take their Tainted Essences. You are then to combine 10 of the essences into a Writhing Mass and throw it into any of their cauldrons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13323] = { id = 13323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag and Drop", description = "Looks like those initiates are increasing in number again. You know what to do...\n\nAt the southern portion of the gate, the new cultists are being trained. They're certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nSlay the fools until you find some, then use them on the subjugators there.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old....", objectives = "Thassarian, aboard the Skybreaker, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13324] = { id = 13324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Prisms Deck", description = "Now that you have gathered all of the Prism cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", progress = "I see that you have managed to complete a deck of Prisms!   Congratulations!", completion = "So you have put together a deck of Prisms.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", objectives = "Return the Prisms Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13325] = { id = 13325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Chaos Deck", description = "Now that you have gathered all of the Chaos cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", progress = "I see that you have managed to complete a deck of Chaos!   Congratulations!", completion = "So you have put together a deck of Chaos.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", objectives = "Return the Chaos Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13326] = { id = 13326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Nobles Deck", description = "Now that you have gathered all of the Nobles cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", progress = "I see that you have managed to complete a deck of Nobles!   Congratulations!", completion = "So you have put together a deck of Nobles.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", objectives = "Return the Nobles Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13327] = { id = 13327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Undeath Deck", description = "Now that you have gathered all of the Undeath cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", progress = "I see that you have managed to complete a deck of Undeath!   Congratulations!", completion = "So you have put together a deck of Undeath.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", objectives = "Return the Undeath Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13328] = { id = 13328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatter the Shards", description = "Atop the battlements of Corp'rethar, the Lich King's minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp'rethar, he will unleash these weapons on our army.\n\nIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.\n\nFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!", progress = "Have you shattered the Lich King's new weapons?", completion = "<Koltira takes the crystal shards from you and speaks in a quiet voice.>\n\nI remember these...\n\nLesser men would easily crumble beneath their assault. You have done well in removing their threat.", objectives = "Bring the Broken Shard of Horror, the Broken Shard of Despair, and the Broken Shard of Suffering to Koltira Deathweaver aboard Orgrim's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13329] = { id = 13329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Gate of Horror", description = "The Conflagration, the ground before Corp'rethar, south of the Ironwall Rampart, is where the Lich King's elite soldiers have formed up to defend the citadel.\n\nLed by a contingent of death knights, a legion of skeletal reavers bars the way. I fear that even when these reavers fall, the Scourge will simply reconstitute them and send them back at us.\n\nI've come up with a plan to stop this, but I have no way of knowing if it will work. Take this solution and use it to dissolve the remains of the reavers.", completion = "<Koltira listens to your report.>\n\nGood. I'll have the engineers mix up as much of that acid as they can before we prepare to assault Corp'rethar with the main force.", objectives = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to use the Volatile Acid to dissolve the remains of 6 Skeletal Reavers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13330] = { id = 13330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Chosen", description = "Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called \"Chosen\" of the Lich King.\n\nGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.", completion = "Not so strong after all, it seems. The Lich King will get what's coming to him.", objectives = "Warbringer Davos Rioht on Orgrim's Hammer has sent you to kill 20 vrykul in Ymirheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13331] = { id = 13331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Alliance Blind", description = "The Alliance is tenacious, I'll give them that, but it'll take more than that to stop us. Take this SGM-3 with you and shoot down the Skybreaker's recon fighters once again.\n\nI doubt the message will get through their thick skulls, but there are enough missiles to keep trying to get our point across. Go and find their fighters flying above the Valley of Fallen Heroes, west of Aldur'thar, and don't come back until you've made wreckage of them.", completion = "Well done, once again. Horde superiority is assured, at least until those Alliance pukes decide to challenge us again.", objectives = "Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13332] = { id = 13332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raise the Barricades", description = "When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.\n\nWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.\n\nTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.", completion = "<Thassarian nods.>\n\nGood. It's not much protection, but it's better than nothing. That gate is still the perfect choke point if the Scourge commanders know what they're doing. We must gain control of as much of the surrounding area as possible.", objectives = "Thassarian, aboard the Skybreaker, wants you to construct 8 Barricades using your Barricade Construction Kit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13333] = { id = 13333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture More Dispatches", description = "Despite our efforts, the Horde continues to send scouts to the area of the Icecrown Glacier, to the west of the Ironwall Rampart and Aldur'thar.\n\nWe can't afford to let the Horde gain the upper hand with this scouting operation. Take the dart gun with you again and show the Orgrim's Hammer scouts no mercy! Bring the captured dispatches to me.\n\nThe Horde's wasted efforts will be our gain.", progress = "Have you intercepted those dispatches?", completion = "<The high captain accepts the dispatches.>\n\nThis is just what we need. Not even the Horde is so stupid as to charge in blindly against the Scourge. With their reports in hand, we'll be well prepared.", objectives = "Capture 6 Orgrim's Hammer Dispatches from Orgrim's Hammer Scouts and bring them to High Captain Justin Bartlett aboard the Skybreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13334] = { id = 13334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodspattered Banners", description = "In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley's dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.\n\nIt falls to you to rid us of this obstacle, and test the resistance before the main body can advance.", completion = "You have removed the Scourge banner-bearers and their minions? Good. Our preparations must continue.", objectives = "Thassarian, aboard the Skybreaker, wants you to kill 5 Scourge Banner-Bearers, 5 Scourge Converters, and 20 Converted Heroes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13335] = { id = 13335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Gate of Horror", description = "The Conflagration, the ground before Corp'rethar, south of the Ironwall Rampart, is where the Lich King's elite soldiers have formed up to defend the citadel.\n\nLed by a contingent of death knights, a legion of skeletal reavers bars the way. I fear that even when these reavers fall, the Scourge will simply reconstitute them and send them back at us.\n\nI've come up with a plan to stop this, but I have no way of knowing if it will work. Take this solution and use it to dissolve the remains of the reavers.", completion = "<Thassarian listens as you describe your successful tests.>\n\nSo the acid worked? Good. We'll need it when the army goes up against the reavers in force.", objectives = "Thassarian, aboard the Skybreaker, wants you to use the Volatile Acid to dissolve the corpses of 6 Skeletal Reavers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13336] = { id = 13336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Chosen", description = "Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called \"Chosen\" of the Lich King.\n\nGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.", completion = "The traitor king will fall. Of that I have no doubt.", objectives = "Knight-Captain Drosche on the Skybreaker has sent you to kill 20 vrykul in Ymirheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13337] = { id = 13337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ironwall Rampart", description = "The Ironwall Rampart overlooks the Valley of Fallen Heroes, west of Aldur'thar. The rampart dominates the fields below on all sides. We will not be able to advance if the rampart cannot be taken, but it is held by Grimkor the Wicked and his Cult of the Damned disciples.\n\nIf you can weaken Grimkor, our forces will know what to expect as we advance. Take this rune of distortion. Unleashing its power near Grimkor's orb at the end of the rampart should be enough to get the necromancer's attention.", completion = "So Grimkor has fallen by your hand? Excellent work. With him out of the way, our chances of taking and holding the rampart during the assault are greatly improved.", objectives = "Defeat Grimkor the Wicked and return to Thassarian aboard the Skybreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13338] = { id = 13338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guardians of Corp'rethar", description = "Corp'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.\n\nWe must weaken its defenses, or our army's strength will break upon its walls.\n\nIts battlements are manned by some of the Lich King's fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.", completion = "I hope your success at Corp'rethar will prove an omen of the battle ahead. The Lich King cannot sit idly by as we march to the very gates of his stronghold.", objectives = "Thassarian, aboard the Skybreaker, wants you to kill 5 Harbingers of Horror and 5 Corp'rethar Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13339] = { id = 13339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatter the Shards", description = "Atop the battlements of Corp'rethar, the Lich King's minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp'rethar, he will unleash these weapons on our army.\n\nIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.\n\nFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!", progress = "Have you shattered the Lich King's new weapons?", completion = "<Thassarian takes the crystal shards from you and speaks in a quiet voice.>\n\nI remember these...\n\nLesser men would easily crumble beneath their assault. You have done well in removing their threat.", objectives = "Bring the Broken Shard of Horror, the Broken Shard of Despair, and the Broken Shard of Suffering to Thassarian, aboard the Skybreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13340] = { id = 13340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Assault", description = "We need more men to join the main assault on Ymirheim.\n\nAny warrior with half a brain can tell you that vrykul are fierce fighters and should not be taken lightly. That goes two-fold for the Ymirjar. They have shown us no restraint in proving why the Lich King deemed them worthy.\n\nGround Commander Xutjja is overseeing the assault. The city itself is located in the center of Icecrown - Xutjja's troops are positioned near the edge of the glacier, north of the city.", completion = "More meat for the grinder. Welcome to hell, soldier.\n\nMy men are leading the assault on the gate from this position, and we're dropping some infiltrators in the city via air - we need more people on both fronts. I have a feeling that this attack will be going on for some time.", objectives = "Report to Ground Commander Xutjja at the edge of the glacier north of Ymirheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13341] = { id = 13341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Assault", description = "We need more men to join the main assault on Ymirheim.\n\nAny warrior with half a brain can tell you that vrykul are fierce fighters and should not be taken lightly. That goes two-fold for the Ymirjar. They have shown no restraint in proving to us why the Lich King deemed them worthy.\n\nGround Commander Koup is overseeing the assault. The city itself is located in the center of Icecrown - Koup's troops are positioned near the edge of the glacier, east of the city.", completion = "Welcome to hell, soldier.\n\nMy men are leading the assault on the gate from this position, and we're dropping some infiltrators in the city via air - we need more people on both fronts. I have a feeling that this attack will be going on for some time.", objectives = "Report to Ground Commander Koup at the edge of the glacier east of Ymirheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13342] = { id = 13342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Bug", description = "Alright, <friend/missy>, time to plant a bug.\n\nRelax, it's not a bug exactly, but it'll serve our purposes.\n\nIn the northern portion of Aldur'thar the cult's void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use their summoning crystal to bring our little spy into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", completion = "You have done well, {class}.\n\nThe messenger has already turned up some valuable information.", objectives = "Thassarian, aboard the Skybreaker, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13343] = { id = 13343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery of the Infinite, Redux", description = "There you are! Or, were we just talking?\n\n<Chromie muses over the temporal possibilities.>\n\nAnyway, the Infinites are after you! Well, not you per-se. Rather, they're after the past version of you that defended the Hourglass of Eternity. You remember, right?\n\nThat was you back then, except it's you now too. Wait, that's not important. What is important is that you head back to the Bronze Dragonshrine and defend yourself and the hourglass from their attacks before you get erased from history!", completion = "Oh my goodness, you made it! I was uncertain.\n\nYou flickered in and out of the time stream there for a moment during the fight! I thought for sure that we'd lost you!\n\nBut here you are safe and sound, with your past self rescued, on the other side of the time loop you were in.\n\nYou're quite the temporal hero, {name}!", objectives = "Chromie, at the top of Wyrmrest Temple, has asked you to travel once more to the Bronze Dragonshrine.\n\nOnce inside, place the Hourglass of Eternity on the ground and help your Past Self to protect it from the forces of the Infinite Dragonflight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13344] = { id = 13344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Bug", description = "The cultists have discovered the last messenger you summoned, {race}.\n\nWhile it was quite informative, it's important that we continue to monitor their every move.\n\nUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur'thar. Then use their summoning crystal to bring another dark messenger into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", completion = "Well done, friend.\n\nThe messenger is up and reporting in as we speak.", objectives = "Thassarian, aboard the Skybreaker, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13345] = { id = 13345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need More Info", description = "The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....\n\nPerhaps it's the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!\n\nI believe the key lies with their researchers. Find out what they're up to and report back to me with the details.", progress = "Have you determined what their researchers are up to, {race}?", completion = "This is alarming, indeed....", objectives = "Thassarian, aboard the Skybreaker, wants you to collect the 3 pages of Cultists' Research from the Cult Researchers at Aldur'thar and use them to create the Cult of the Damned Thesis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13346] = { id = 13346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For The Wicked", description = "These fools have actually stumbled upon something that could pose a serious threat to our plans!\n\nThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers...", objectives = "Thassarian, aboard the Skybreaker, wants you to defeat Alumeth the Ascended at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13347] = { id = 13347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reborn From The Ashes", description = "Our fate is emblazoned upon our souls at birth. Bolvar's fall, while tragic, was unavoidable.\n\nAll that you can do now is honor your hero, {name}. Collect Bolvar's shield from the field of battle and return it to your king. When you present the shield to Varian, tell him this: \"All is not lost. From the ashes of the fallen will rise a force that will unite nations and purge the evil from this world.\"\n\nHe mustn't lose faith. Go now, {name}. Your people need a hero. They need you.", progress = "<King Wrynn brushes away a tear.>\n\n<King Wrynn nods.>\n\nThis is my fault.", completion = "The Dragon Queen is right, {name}. All is not lost. I will be the force that rises from the ashes and I will purge the evil of the Horde from this world. The deaths of our brothers and sisters will not have been in vain.", objectives = "Gather Fordragon's Shield from the field of battle at Angrathar the Wrath Gate and return it to King Varian Wrynn at Stormwind Keep in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13348] = { id = 13348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futility", description = "Do you see now?  Sending your men against the prince's armies just swells their numbers.\n\nI don't expect you to understand... you'll probably just end up like the others.  You'd best return to whoever sent you.  They might be worried.", completion = "There you are.  Nice work down in the valley.  The carnage was visible all the way up here.\n\nAre you okay?  You look like you've seen a ghost.", objectives = "Return to Koltira Deathweaver aboard Orgrim's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13349] = { id = 13349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cradle of the Frostbrood", description = "We need to keep our momentum going.  Let's not give the Scourge forces any respite.\n\nSindragosa's Fall lies east just beyond the Valley of Lost Hope.  The Cult of the Damned operate there, under close supervision of the Lich King's undead vrykul lackeys.\n\nIt is a place of great power, possibly a blue dragonflight graveyard.  The feared frostbrood are raised there from the bones of blue dragons.\n\nAn attack there would have great impact on the enemy's access to frost wyrms.  Are you up to it, {name}?", completion = "You've done well, {name}.  You might want to rest for a while.  You look a little pale.", objectives = "Koltira Deathweaver aboard Orgrim's Hammer wants you to slay 5 Wyrm Reanimators, 8 Cultist Corrupters and 3 Vrykul Necrolords at Sindragosa's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13350] = { id = 13350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For The Wicked", description = "It's Alumeth... He's growing in power again. I can sense it. Again his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nReturn to his chamber in the north portion of Aldur'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers...", objectives = "Thassarian, aboard the Skybreaker, wants you to defeat Alumeth the Ascended at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13351] = { id = 13351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sneak Preview", description = "Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from the Alliance.\n\nOur next focus will be Aldur'thar, the gate of desolation. Fly down and become familiar with it and with the enemies posted there.\n\nWhen you return, I will have your missions prepared.", completion = "Well and good, {class}.\n\nNow that you've seen firsthand what we're up against, it's time to get to work...", objectives = "Koltira, aboard Orgrim's Hammer, wants you to fly down to the gate of desolation, visiting the south, central, north, and northwest regions of the gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13352] = { id = 13352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag and Drop", description = "The Cult of the Damned hold the gate of desolation, eh? No surprise there.\n\nTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They're almost certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nKill the fools until you find one, {class}, then use it on a subjugator.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old....", objectives = "Koltira, aboard Orgrim's Hammer, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13353] = { id = 13353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag and Drop", description = "Looks like those initiates are increasing in number again. You know what to do...\n\nAt the southern portion of the gate, the new cultists are being trained. They're certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nSlay the fools until you find some, then use them on the subjugators there.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old....", objectives = "Koltira, aboard Orgrim's Hammer, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13354] = { id = 13354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chain of Command", description = "Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.\n\nWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, {race}, is a worthy enough goal for now.\n\nSeek out these overseers and return to me when they have been dispatched.", completion = "Well done, {race}. But don't break your arm patting yourself on the back. They'll have those overseers replaced in no time...", objectives = "Koltira aboard Orgrim's Hammer wants you to go to Aldur'thar and defeat Overseer Faedris, Overseer Savryn, Overseer Veraj, and Overseer Jhaeqon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13355] = { id = 13355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannot Reproduce", description = "I smell their cauldrons from here, but that's not plague they're cooking.\n\nPledges to the cult are forced to drink a concoction that steals their will and enslaves them forever to the Lich King.\n\nSome say the potion contains the twisted soul of a being who was tormented before being mercilessly slaughtered, but I've never been able to reproduce it...\n\nFill this flask with a sample from each of the three cauldrons in the northwest region of the gate and bring it to Chief Engineer Copperclaw.", progress = "Whatdya got there, {class}?", completion = "<Copperclaw pours the contents of the flask into his particle analyzer.>\n\nAhh... I know just the thing!", objectives = "Koltira aboard Orgrim's Hammer wants you to use the Partitioned Flask at each of the 3 Cultists' Cauldrons at Aldur'thar, then bring it to Chief Engineer Copperclaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13356] = { id = 13356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retest Now", description = "This should do the trick!\n\nThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... Its only effect will be to detect any cultist's essence once you've defeated them.\n\nWhen you've collected a bunch of essences, throw the writhing mass of twisted souls into any of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", completion = "Wahoo!\n\nThat'll teach 'em!", objectives = "Chief Engineer Copperclaw aboard Orgrim's Hammer wants you to throw a Writhing Mass into a cauldron at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13357] = { id = 13357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retest Now", description = "Those twisted cultists are looking for souls to put in their crazy-juice? Then let's help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence.\n\nOnce you've collected a bunch of 'em, throw the writhing mass of twisted souls in one of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", completion = "Wahoo!\n\nThat'll teach 'em!", objectives = "Chief Engineer Copperclaw aboard Orgrim's Hammer wants you to throw a Writhing Mass into a cauldron at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13358] = { id = 13358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Bug", description = "Alright, <friend/missy>, time to plant a bug.\n\nRelax, it's not a bug exactly, but it'll serve our purposes.\n\nIn the northern portion of Aldur'thar, the cult's void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use the cultists' summoning crystal to bring our little spy into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", completion = "You have done well, {class}.\n\nThe messenger has already turned up some valuable information.", objectives = "Koltira, aboard Orgrim's Hammer, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13359] = { id = 13359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Dragons Fell", description = "A whole brood of blue dragons fell here.  And now, one by one, they're being raised by his servants.\n\nHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I'll show you exactly how he did it.", progress = "Did you get the dust, {name}?", completion = "Even the mighty wyrms had to heed his call.  How is a simple mortal like you going to resist him?", objectives = "Matthias Lehner at Sindragosa's Fall wants you to obtain 6 Whelp Bone Dusts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13360] = { id = 13360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for Answers", description = "You have a lot of questions, {name}.  You're the only one who can see me because you touched something that once belonged to him... don't you remember?\n\nYou don't know what it is?  Well I can't just tell you... that would make him really mad.  He's not just a prince anymore... he's the king!\n\nMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.", completion = "There you are.  I started to wonder whether you'd show up.", objectives = "Speak to Matthias Lehner at the Court of Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13361] = { id = 13361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter and the Prince", description = "Before the prince became a king, he fought many battles... but only one where he came close to dying.\n\nIt was fought right here.  After you let me show you what happened, you'll understand everything.\n\nFind a bloodstained stone and pick it up from the floor.  You'll see what happened.", progress = "Did you see, {name}?  Did you?", completion = "After that fight, the prince realized what was holding him back was that he was still human... he could still feel... he could still bleed.  He still had a heart.\n\nThe first thing he did when he became king was to rid of himself of it.  He threw it down the pit where we first met.  And you, {name}, were the first person to touch it since.", objectives = "Matthias Lehner in the Court of Bones wants you to look for a Bloodstained Stone and complete the Prince's Destiny.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13362] = { id = 13362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge is a Terrible Burden", description = "Now you know what you're up against, {name}.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.\n\nThe heart was his weakness and now he knows you've found it.\n\nIf you're going to go back for it, you'd best bring help.  He will not leave it unguarded again.", completion = "Little kid's ghost... Arthas's heart... you'd better slow down... you're making my head spin.", objectives = "Report back to Koltira aboard Orgrim's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13363] = { id = 13363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Aid", description = "There were rumors about the events you speak of among the death knights.  I always expected the story to be more... symbolic.\n\nWe must warn others, but we must be discreet.  As soon as the Lich King knows we're making our move, he'll move the location of the heart -- we'll never get a chance like this again.\n\nThe Horde and the Alliance have been infiltrated by the Cult of the Damned before.  The Ebon Blade operates too close to the Scourge.\n\nWe have to speak to Tirion Fordring and his Argent Crusade.", completion = "Heavy words, {name}.  If it were somebody else saying them, I'd be likely to judge them insane.", objectives = "Speak to Highlord Tirion Fordring at the Crusader's Pinnacle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13364] = { id = 13364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirion's Gambit", description = "Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.\n\nAnd now I learn that it might be Arthas's own heart... a thing containing the last bit of his remaining humanity.\n\nThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!\n\nMeet me at the cathedral's entrance.  Be sure to bring a cultist's hood -- we're going incognito.", completion = "I do not view what we just went through as a failure, {name}... quite the opposite.\n\nBy allowing me to peer into his heart, you allowed me to confirm what I needed to know.  There is no Arthas Menethil anymore -- there is only the Lich King.", objectives = "Tirion Fordring, at the Crusader's Pinnacle, wants you to obtain and wear a Cultist Acolyte's Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13365] = { id = 13365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Bug", description = "The cultists have discovered the last messenger you summoned, {race}.\n\nWhile it was quite informative, it's important that we continue to monitor the cult's every move.\n\nUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur'thar. Then use their summoning crystal to bring another dark messenger into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", completion = "Well done, friend.\n\nThe messenger is up and reporting in as we speak.", objectives = "Koltira, aboard Orgrim's Hammer, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13366] = { id = 13366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need More Info", description = "The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....\n\nPerhaps it's the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!\n\nI believe the key lies with their researchers. Find out what they're up to and report back to me with the details.", progress = "Have you discovered what their researchers are up to, {class}?", completion = "This is alarming, indeed....", objectives = "Koltira, aboard Orgrim's Hammer, wants you to collect the 3 pages of Cultists' Research from the Cult Researchers at Aldur'thar and use them to create the Cult of the Damned Thesis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13367] = { id = 13367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For The Wicked", description = "These fools have actually stumbled upon something that could pose a serious threat to our plans!\n\nThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers...", objectives = "Koltira, aboard Orgrim's Hammer, wants you to slay Alumeth the Ascended at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13368] = { id = 13368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For The Wicked", description = "It's Alumeth... He's growing in power again. I can sense it. Again his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nReturn to his chamber in the north portion of Aldur'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.\n\nHurry, {race}! Destroy him while there's still time!", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers...", objectives = "Koltira, aboard Orgrim's Hammer, wants you to slay Alumeth the Ascended at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13369] = { id = 13369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate, Up Against Your Will", description = "At the behest of Lady Proudmoore, I will allow a diplomatic mission to Orgrimmar to question the Horde's Warchief, Thrall. You will assist her in this journey and keep her safe from harm. Return to me with news from Orgrimmar.\n\nSpeak to Jaina when you are ready to leave.", sourceObjective = "Assist Lady Jaina Proudmoore in Orgrimmar. Speak to the Warchief of the Horde, Thrall, at Orgrimmar on the continent of Kalimdor.", completion = "The Horde does not want war, {race}. Listen well...", sourceObjectiveStatus = "unverified-source-field" }
quests[13370] = { id = 13370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Coup", description = "Your champion, Bolvar, died in defense of our world. The Horde is saddened by the loss of such a great hero, but the Horde was not responsible for the cowardly attacks made by Putress at the Wrath Gate. We have also lost mighty heroes because of this betrayal.\n\nTell your king that we will do everything in our power to bring the perpetrators of this cowardly act to justice. We will do all that we can to avoid conflict with the Alliance, but we will not hesitate to defend ourselves if provoked.", completion = "They have lost the Undercity? Then the time to strike is now. We will deal with Putress ourselves and retake the Ruins of Lordaeron for the Alliance!", objectives = "Use the portal in Grommash Hold to return to Stormwind Keep and deliver Thrall's message to King Varian Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13371] = { id = 13371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Killing Time", description = "I sent Broll and Valeera to the Undercity before you left for Orgrimmar. In fact, they're now stationed outside the sewer entrance to the ruins, awaiting orders.\n\nLady Proudmoore will open a portal to our forces outside the Undercity. Go there and report to Broll. Jaina and I will be close behind.", completion = "Who are you supposed to be? Varian said he'd send heroes.", objectives = "Use the Portal to the Undercity inside Stormwind Keep to teleport to the Undercity. Report to Broll Bearmantle when you arrive at your destination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13372] = { id = 13372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key to the Focusing Iris", description = "A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron's clutches. To mortal ears it is nearly painful to be in the presence of the stone.\n\nSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.", progress = "{name}, you have come into contact with a key to the focusing iris! Do you have it upon your person?\n\n\n\nHow did you ever come into its possession? Oh, Sapphiron still had his?", completion = "These keys are held by the most ancient members of the blue dragonflight. Only they are entrusted with them by their master, Malygos.\n\nThis is the break that we've been waiting for to strike at the Aspect of Magic!\n\n<The queen of dragons studies you for a brief moment.>\n\nYou are not able to use the key as-is to access the Focusing Iris, but I can imbue you with a portion of my power; enough to enable you to use it to open the iris a fraction.\n\nIt will be enough to draw Malygos's ire!", objectives = "Deliver the Key to the Focusing Iris to Alexstrasza the Life-Binder atop Wyrmrest Temple in the Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13373] = { id = 13373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fringe Science Benefits", description = "I installed our infra-green technology into commandeered bombers; it'll protect you on your first mission into enemy territory!  Speak with Rizzy Ratchwiggle to get a bomber, then fly into The Bombardment!\n\nYou'll have bombs and rockets and shields.  Keep the shields charged and use bombs on the ground Scourge at The Bombardment.  Come back after you hit your targets, and more work will await you.", completion = "Hah, you got them!  How did you like the bomber?  I hope you got the hang of it, because I have more missions for you...", objectives = "Fringe Engineer Tezzla wants you to kill 40 Bombardment Infantry, 8 Bombardment Captains and 15 Gargoyle Ambushers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13374] = { id = 13374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amped for Revolt!", description = "{name}, only our best pilots are given a mission like this, one deep, deep into enemy territory with only the power of infra-green technology to protect you!\n\nRequest another bomber from Rizzle, and this time fly it through the Valley of Lost Hope.  You have both air and ground targets on this mission, so keep your eyes open and your shields at full!\n\nGood luck!", objectives = "Fringe Engineer Tezzla wants you to kill Bombardment Infantry, Gargoyle Ambushers, Frostbrood Sentries and Scourge War Machines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13375] = { id = 13375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heroic Key to the Focusing Iris", description = "A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron's clutches. To mortal ears it is nearly painful to be in the presence of the stone.\n\nSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.", progress = "{name}, you have come into contact with a key to the iris! Do you have it upon your person?\n\n\n\nHow did you ever come into its possession? Oh, Sapphiron still had his?", completion = "These keys are held by the most ancient members of the blue dragonflight. Only they are entrusted with them by their master, Malygos.\n\nThis is the break that we've been waiting for to strike at the Aspect of Magic!\n\n<The queen of dragons studies you for a brief moment.>\n\nYou are not able to use the key as-is to access the Focusing Iris, but I can imbue you with a portion of my power; enough to enable you to use it to open the iris a fraction.\n\nIt will be enough to draw Malygos's ire!", objectives = "Deliver the Heroic Key to the Focusing Iris to Alexstrasza the Life-Binder atop Wyrmrest Temple in the Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13376] = { id = 13376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Total Ohmage: The Valley of Lost Hope!", description = "{name}, the struggle continues.  Lucky for us, we're stocked up on bombs and rockets!  Time for another bombing mission  --  this one's a long one, through the Bombardment and into the Valley of Lost Hope.  Head back out with an infra-green bomber and blow those Scourge into little scourge-lets!", completion = "Great work, {name}.  While you were out, I heard other gunners talking about you... I think you have a real future in air offense!", objectives = "Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 20 Gargoyle Ambushers, 12 Frostbrood Sentries and 12 Scourge War Machines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13377] = { id = 13377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle For The Undercity", description = "Deep inside the bowels of the Undercity hides the assassin responsible for the deaths of Bolvar and our brave soldiers at the Wrath Gate.\n\nVarian has brought the full might of the Alliance with him to assist in the take down. Join him and Lady Proudmoore in the manhunt and earn your place among the greatest champions of the Alliance!\n\nSpeak to King Varian Wrynn when you are ready.", completion = "For too long have the Horde been left unchecked. We allowed their territories to prosper and in return for our generosity they plotted and planned our demise.\n\nPeace? Useless... It's gotten us nowhere. We have lost some of our greatest heroes to \"peace.\" Let us see what battle brings...\n\nReturn to Northrend, {name}. Conquer it for your king - FOR THE ALLIANCE!", objectives = "Assist King Varian Wrynn and Lady Jaina Proudmoore in bringing Grand Apothecary Putress to justice! Report to King Varian Wrynn should you succeed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13378] = { id = 13378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Engineer Copperclaw", description = "Speak with Chief Engineer Copperclaw." }
quests[13379] = { id = 13379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Technology", description = "Tezzla is the one you want to meet, yes she is... she mastered a new wavelength, infra-green, and used it to hide herself near the Scourge!  Near enough to bomb them!\n\nI'll give you infra-green vision so you can find her hiding above Aldur'thar, the Desolation Gate.  Go, go... I know she has work for brave heroes eager to blow up!  I mean... eager to blow up the Scourge!\n\nAnd {name}, the Alliance has stolen our technology and has their own hidden airport nearby.  Avoid the dome with the Alliance banners!", completion = "Yes, yes!  You found me!  And just in time!", objectives = "Speak with Fringe Engineer Tezzla.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13380] = { id = 13380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leading the Charge", description = "Infra-green technology allows us to stay hidden here, right over the Scourge's nose!  What's more, we installed infra-green in specially constructed bombers... but not to hide them, no!  We use infra-green tech to shield them!\n\nSpeak with Karen No and request a bomber.  Fly it over the Bombardment... use its shields and turret to protect yourself, and use the bomb launcher to hit Scourge targets.  Practice well, then return to me and I'll have an even more vital mission for you!", completion = "I could hear your explosions from here, {name}.  How did the shields work?  Did they keep your bomber intact?\n\nI hope they did, because now I have more missions for you....", objectives = "Kibli Killohertz wants you to kill 40 Bombardment Infantry, 8 Bombardment Captains and 15 Gargoyle Ambushers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13381] = { id = 13381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watts My Target", description = "Put on your lucky socks, {name}, and say your favorite prayers.  This next mission will test your wit and fortitude like a visit from the in-laws!\n\nRequest another bomber from Karen No.  Take it beyond The Bombardment and over the Valley of Lost Hope.  You have more targets this time, both on the land an in the air.  Keep your shields charged and your ammo loaded, {name}!  I'll see you when it's over.", objectives = "Kibli Killohertz wants you to kill Bombardment Infantry, Gargoyle Ambushers, Frostbrood Sentries and Scourge War Machines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13382] = { id = 13382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting the Hertz: The Valley of Lost Hope", description = "The fight goes on!  Your new orders arrived for a long-range bombing mission through the Bombardment and into the Valley of Lost Hope -- when you're ready, ask Karen for a bomber and pour those bombs and rockets onto the Scourge!", completion = "Welcome back, {name}.  How was the battle?  Exciting?  Take a rest for now.  But come back when you have fresh orders.\n\nFor the Alliance!", objectives = "Kibli Killohertz wants you to kill 50 Bombardment Infantry, 20 Gargoyle Ambushers, 12 Frostbrood Sentries and 12 Scourge War Machines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13383] = { id = 13383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killohertz", description = "The goblins got lucky and found a new energy.  They call it infra-green, and I'll be a one-eyed ogre if those psychos didn't strike green gold.\n\nGo find Kibli Killohertz.  He's leading the reverse engineering efforts of infra-green, at a small, hidden Alliance airport above Aldur'thar, the Desolation Gate.  I'll give you infra-green vision to help you find it.  Go to the dome with our Alliance banners -- if you fly near the Horde airport then you'll be in a load of green trouble.", completion = "Yes, yes, yes!  A thousand times, hello!", objectives = "Chief Engineer Boltwrench wants you to find Kibli Killohertz at the hidden Alliance airport above Aldur'thar, the Desolation Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13384] = { id = 13384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment at the Eye of Eternity", description = "Now that you have access to the focusing iris it's time to put that key to use.\n\nAs much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.\n\n<Krasus says this last with a great deal of trepidation.>\n\n{name}, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.", progress = "Only Malygos carries the Heart of Magic. It is his most prized possession.", completion = "This is a very sad day, not only for dragonkind, but for all of the living creatures of Azeroth. We have lost one of our most thoughtful, intelligent and ancient friends. Magic is now without its guardian.\n\nLet us hope that this was a wise decision in the coming years, {name}. A storm is still brewing on the horizon and now we are without one of our most powerful defenders.", objectives = "Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic.\n\nThis quest is for the Normal mode, 10-person version of The Eye of Eternity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13385] = { id = 13385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic Judgment at the Eye of Eternity", description = "Now that you have access to the focusing iris it's time to put that key to use.\n\nAs much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.\n\n<Krasus says this last with a great deal of trepidation.>\n\n{name}, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.", progress = "Only Malygos carries the Heart of Magic. It is his most prized possession.", completion = "This is a very sad day, not only for dragonkind, but for all of the living creatures of Azeroth. We have lost one of our most thoughtful, intelligent and ancient friends. Magic is now without its guardian.\n\nLet us hope that this was a wise decision in the coming years, {name}. A storm is still brewing on the horizon and now we are without one of our most powerful defenders.", objectives = "Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic.\n\nThis quest is for the Heroic mode, 25-person version of The Eye of Eternity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13386] = { id = 13386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploiting an Opening", description = "I've got an interesting assignment for you, {name}.  If you're up for a challenge, that is.\n\nWe've been tipped off about an opening below Icecrown Citadel.  Our engineers have studied the layout and have decided it's a structural weakness.\n\nWe've sent some men there along with some \"borrowed\" saronite bombs.  They're under Captain Kendall's command.\n\nWith a little help we could deal a huge blow to the forces of the Scourge.  What do you say, {name}?", completion = "Hail, {name}.  Thassarian mentioned you'd be dropping by.  Any friend of Thassarian's is my friend.  Well, any living friend of Thassarian, that is...  He does keep odd company.", objectives = "Speak to Captain Kendall below Icecrown Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13387] = { id = 13387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Perimeter", description = "The saronite bombs are in place, {name}.  We're only going to get one shot at this, however.  Let's make it count.\n\nWe need temporary control of the area for a safe detonation.  Let's try to put a dent in the Scourge's numbers.", completion = "You're as good as Thassarian said.  Good job!", objectives = "Captain Kendall at Icecrown Citadel wants you to slay 10 Hulking Horrors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13388] = { id = 13388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set it Off!", description = "Things are looking good.  Let's do this.\n\nThe stack of bombs is right near the pit.  I'll start to evacuate the men.", completion = "These bombs look pretty potent.  They should at least put a dent in the surrounding structure.", objectives = "Captain Kendall, below Icecrown Citadel, wants you to go to the nearby Saronite Bomb Stack to light the fuse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13389] = { id = 13389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Short Fuse", description = "As you light the fuse, you notice that it is consumed by fire far quicker than you would expect.\n\nThe bombs are about to go off and your best chance at surviving is to lean towards the pit and hope the fall doesn't kill you.", completion = "This pulsing object is covered in a thick layer of ice.  It shimmers strangely beneath the water.", objectives = "Look for clues wherever the fall takes you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13390] = { id = 13390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Voice in the Dark", description = "The object is not a crystal at all, but some form of organ, encased in ice.\n\nAs you touch it, your hand reels in horrible pain.  You feel as if your hand has been cut, yet there is no visible wound.\n\nAs you collect your thoughts, you hear a young boy's voice nearby.\n\n\"You really shouldn't have done that.\"", completion = "I saw him get rid of it, you know?  He threw it all the way down here.\n\nSaid he wouldn't need it anymore.  Said it made him weak.", objectives = "Investigate the nearby voice in Naz'anak, the Forgotten Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13391] = { id = 13391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Hide", description = "You shouldn't have touched it.  But now that you did, he's going to come looking for you.\n\nAnd he'll find you.  Unless you hide yourself from him.\n\nBring me blood from the faceless ones if you want to live!", progress = "Did you get the blood?", completion = "What are you waiting for?  You have to rub it on you!\n\nQuick!  Or he'll see you!", objectives = "Matthias Lehner wants you to obtain 3 Faceless One's Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13392] = { id = 13392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Surface", description = "You should leave now.  You'll find a portal behind me.  It'll take you to the surface.\n\nWe'll meet again.  He'll be looking for you.\n\nIt's only a matter of time until he finds you.", completion = "It's you, {name}!  We thought you were a goner.\n\nThat explosion of yours put quite a bit of hurt on the Scourge.  Nearly took Captain's Kendall's eyebrows off in the process...", objectives = "Return to Thassarian aboard the Skybreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13393] = { id = 13393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Repairs", description = "All right.  Let's not celebrate just yet.  We need to capitalize on the momentum we've gathered with our little bombing mission.\n\nWe've spotted a workable Horde demolisher-class catapult in the field below.  The geist seem to be taking it apart.\n\nIf you can put it back together, we'll be able to do some serious damage to the Scourge's armies in the Valley.\n\nSure, you'll be a little outnumbered, but I've a lot of faith in you!", progress = "The demolisher has suffered much damage.", completion = "The demolisher has seen better days, but the structure hasn't suffered any permanent damage.  The parts you obtained should be enough to get it running again, at least temporarily.", objectives = "Thassarian, aboard the Skybreaker, wants you to collect 5 Demolisher Parts from the Scavenging Geists and take them to the Wrecked Demolisher in the Valley of Lost Hope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13394] = { id = 13394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Your Worst", description = "You're going to use this machine against the Scourge?  You're not going to win against them like that.\n\nYou can destroy hundreds... even thousands of them.  But you won't win.  Not out here.\n\nWhen you're done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you're up against.", completion = "You see?  You killed your fair share, but for every one you destroyed, another rose from the dirt to take its place.\n\nYou don't know what you're up against, {name}.  Let me show you.", objectives = "Use the Refurbished Demolisher to destroy 150 Decomposed Ghouls, 20 Frostskull Mages and 2 Bone Giants in the Valley of Lost Hope. Speak to Matthias Lehner at the First Legion Forward Camp when you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13395] = { id = 13395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Army of the Damned", description = "You probably think you're quite strong -- fighting these undead and crushing their bones beneath your war machines.\n\nThat is nothing compared to the strength it took to create them.\n\nI saw the prince do it himself.  I can show you how it happened... if you'd like.", completion = "The prince's true power wasn't his ability to make armies out of corpses... that was easy.\n\nBut killing his own men, with whom he'd shared many battles... the prince's true power was his ability to do what had to be done.", objectives = "Matthias Lehner at the First Legion Forward Camp wants you to raise an army of 100 Ghoulish Minions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13396] = { id = 13396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futility", description = "Do you see now?  Sending your men against the prince's armies just swells their numbers.\n\nI don't expect you to understand... you'll probably just end up like the others.  You'd best return to whoever sent you.  They might be worried.", completion = "Nice shooting, {name}.  The Scourge never had a chance.\n\nAre you feeling okay?  You look like you've seen a ghost.  Not that it would be an unusual thing around these parts, now that I think about it.", objectives = "Return to Thassarian aboard the Skybreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13397] = { id = 13397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sindragosa's Fall", description = "You're a real star, {name}.  See, when I give one of these other soldiers an assignment, the odds of them getting it done are about fifty-fifty.  The odds of them coming back... well, slightly worse.\n\nBut with you, it's always a guaranteed thing.  Like gnomish clockwork!\n\nAnyway, I have another one for you.  Sindragosa's Fall, east of the valley.  There is some serious cultist activity, including and not limited to, the raising of frost wyrms.  I need you to go kick their teeth in.\n\nI hate cultists.", completion = "Nice job, {name}.  You make the rest of us look bad!", objectives = "Thassarian aboard the Skybreaker wants you to slay 5 Wyrm Reanimators, 8 Cultist Corrupters and 3 Vrykul Necrolords at Sindragosa's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13398] = { id = 13398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Dragons Fell", description = "A whole brood of blue dragons fell here.  And now, one by one, they're being raised by his servants.\n\nHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I'll show you exactly how he did it.", progress = "Did you get the dust, {name}?", completion = "Even the mighty wyrms had to heed his call.  How is a simple mortal like you going to resist him?", objectives = "Matthias Lehner at Sindragosa's Fall wants you to obtain 6 Whelp Bone Dusts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13399] = { id = 13399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for Answers", description = "You have a lot of questions, {name}.  You're the only one who can see me because you touched something that once belonged to him... don't you remember?\n\nYou don't know what it is?  Well I can't just tell you... that would make him really mad.  He's not just a prince anymore... he's the king!\n\nMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.", completion = "There you are.  I started to wonder whether you'd show up.", objectives = "Speak to Matthias Lehner at the Court of Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13400] = { id = 13400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter and the Prince", description = "Before the prince became a king, he fought many battles... but only one where he came close to dying.\n\nIt was fought right here.  After you let me show you what happened, you'll understand everything.\n\nFind a bloodstained stone and pick it up from the floor.  You'll see what happened.", progress = "Did you see, {name}?  Did you?", completion = "After that fight, the prince realized what was holding him back was that he was still human... he could still feel... he could still bleed.  He still had a heart.\n\nThe first thing he did when he became king was to rid of himself of it.  He threw it down the pit where we first met.  And you, {name}, were the first person to touch it since.", objectives = "Matthias Lehner in the Court of Bones wants you to look for a Bloodstained Stone and complete the Prince's Destiny.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13401] = { id = 13401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge is a Terrible Burden", description = "Now you know what you're up against, {name}.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.\n\nThe heart was his weakness and now he knows you've found it.\n\nIf you're going to go back for it, you'd best bring help.  He will not leave it unguarded again.", completion = "Slow down, {name}.  Why don't you start again... from the beginning?", objectives = "Report back to Thassarian aboard the Skybreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13402] = { id = 13402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirion's Help", description = "It's not the first time I've heard that story about Arthas and his heart... always thought it was some made-up tale to impress the rank and file.\n\nWe must act on this information immediately.  Unfortunately, we must do so in secret.\n\nArthas's agents are everywhere and if he finds out, our plan is dead in the water.\n\nWe need to take this to the Argent Crusade.  Every single paladin in that order was hand-picked by Tirion himself.  If there's anyone free of cultist infiltration, it's those guys.", completion = "Heavy words, {name}.  If it were somebody else saying them, I'd be likely to judge them insane.", objectives = "Speak to Highlord Tirion Fordring at the Crusader's Pinnacle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13403] = { id = 13403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirion's Gambit", description = "Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.\n\nAnd now I learn that it might be Arthas's own heart... a thing containing the last bit of his remaining humanity.\n\nThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!\n\nMeet me at the cathedral's entrance.  Be sure to bring a cultist's hood -- we're going incognito.", progress = "Light be with you, {name}.", completion = "I do not view what we just went through as a failure, {name}... quite the opposite.\n\nBy allowing me to peer into his heart, you allowed me to confirm what I needed to know.  There is no Arthas Menethil anymore -- there is only the Lich King.", objectives = "Tirion Fordring, at the Crusader's Pinnacle, wants you to obtain and wear a Cultist Acolyte's Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13404] = { id = 13404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Static Shock Troops: the Bombardment", description = "This is a short-ranged mission, over The Bombardment.  A good warm up.  Ready?", completion = "Welcome back, {name}.  A short mission, but invigorating, yes?  Take a rest for now.  But come back when you have fresh orders.", objectives = "Kibli Killohertz wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13405] = { id = 13405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Strand of the Ancients", description = "The fight in Northrend is not only against the armies of the Lich King, but also against those of the Horde.\n\nA powerful titan relic has been found in the Strand of the Ancients.  As you might know, we dwarves have been custodians of such artifacts for years and as such we're their rightful keepers.\n\nIn this case, the Horde has developed a keen interest in pilfering the relic from the titan ruins.  They're certain to use it as a weapon against us; we must do whatever we can to stop them.", objectives = "Win a Strand of the Ancients battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13406] = { id = 13406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Wavelength: The Bombardment", description = "Ready to warm up with a short bombing mission?  You have your orders, and we have our bombers stocked and ready.", completion = "Hah, you got them!  I could hear their Scourge parts clatter off the mountain walls.  Good work.  We'll have more for you soon...", objectives = "Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13407] = { id = 13407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Strand of the Ancients", description = "Just because we march into Northrend to smash the Scourge, doesn't mean we get to take a break from crushing the Alliance.\n\nThose Explorers' League dwarves have found the location of a powerful titan relic and we'll be damned if we let the Alliance take control of it.\n\nGo, {name}, and destroy our enemies.  Make them see that no matter where we meet, they remain our sworn enemies.", objectives = "Win a Strand of the Ancients battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13408] = { id = 13408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", progress = "{name}, return to me when you have aided in the capture of each of the forts!", completion = "Well done, {name}.  Your actions in the field are instrumental in our battle for Hellfire Peninsula.", objectives = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13409] = { id = 13409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", completion = "Nice work, {name}.  I could almost hear the battles waged at those forts.  I wish I was there to see them!", objectives = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13410] = { id = 13410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", completion = "Well done, {name}.  Your actions in the field are instrumental in our battle for Hellfire Peninsula.", objectives = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13411] = { id = 13411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", completion = "Nice work, {name}.  I could almost hear the battles waged at those forts.  I wish I was there to see them!", objectives = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13412] = { id = 13412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corastrasza", description = "Greetings, {class}. Might I impose on you for a favor?\n\nCorastrasza is the sister of Raelorasz - the red dragon in charge of our outpost here. Against his will, she has ascended to one of the upper rings of the Nexus to observe some frighteningly powerful blue drakes.\n\nThough he will never say it, he worries about her, and would welcome any news of her well-being.\n\nPlease seek her out. Ask her to put her pride aside and send word to her brother.", completion = "It's quite presumptuous of you to interfere in the personal affairs of a dragon, don't you think, {race}?\n\nThat aside, it would be wrong of me not to let my brother know that I am well. You may tell your meddling friend that I will keep my brother abreast of my actions.", objectives = "Librarian Serrah wants you to speak to Corastrasza in Coldarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13413] = { id = 13413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aces High!", description = "You possess the courage to draw so near to Malygos' lair, mortal? Or is it simply ignorance? Soon we shall know....\n\nI am a seasoned trainer of the graceful drakes of the red dragonflight. My business here is to study the enemy and teach my precious pets the tactics that will be most effective when we face the master of the blues.\n\nTo demonstrate your nerve and ability, I will allow you to ride one of my drakes against the enemy's minions.\n\nThe opportunity is yours for the asking...", progress = "Well, mortal, what do you think of my pets?", completion = "My drake tells me that with practice, you might become a capable combatant.\n\nVery well, then. In the interest of our war on Malygos, I shall allow you to practice with my pets at your leisure.\n\nMake ready, {race}, for he is a fierce and unforgiving opponent.", objectives = "Corastrasza on the upper ring of the Nexus in Coldarra wants you to ride her drake and kill 5 Scalesworn Elites.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13414] = { id = 13414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aces High!", description = "Again we meet, {race}. I confess, your presence is beginning to grow on me.\n\nAm I correct in assuming that you've come to hone your aerial combat skills?\n\nAs always, my pets stand ready to bring fiery destruction to the enemy.\n\nSpeak, and they shall be at your disposal.", progress = "Yes, {race}?", completion = "I noticed some improvement today, {class}. At moments, it was as if you were one with the drake.\n\nYou are welcome to practice with my precious pets at your leisure.", objectives = "Corastrasza on the upper ring of the Nexus in Coldarra wants you to ride her drake and kill 5 Scalesworn Elites.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13415] = { id = 13415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Library Console", description = "Norgannon's shell is within our reach, {name}. Take the inventor's disk into the library's interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon's shell. There are probably enough schematics stored there to keep Ironforge's engineers occupied for years!\n\nAnyway, use the disk to recover the shell. Hopefully, Mimir hasn't decided to put any more obstacles in our way.", progress = "The console appears to have an opening for the inventor's disk.", completion = "<You insert the disk into the console. Suddenly, lights on its surface illuminate and a mechanical voice speaks.>\n\nInventor's disk authenticated. Welcome back, Keeper Mimir.", objectives = "Take the Inventor's Disk to the Inventor's Library Console inside the Inventor's Library.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13416] = { id = 13416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Library Console", description = "Norgannon's shell is within our reach, {name}. Take the inventor's disk into the library's interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon's shell. There are probably enough schematics stored there to keep Ironforge's engineers occupied for years!\n\nAnyway, bring the disk to the console. Hopefully, Mimir hasn't decided to put any more obstacles in our way.", progress = "The console appears to have an opening for the inventor's disk.", completion = "<You insert the disk into the console. Suddenly, lights on its surface illuminate and a mechanical voice speaks.>\n\nInventor's disk authenticated. Welcome back, Keeper Mimir.", objectives = "Take the Inventor's Disk to the Inventor's Library Console inside the Inventor's Library.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13417] = { id = 13417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Bronzebeard", description = "That does it! We finally have the keystone... It's beautiful! I've been around the world more than once, but this thing's got me all jittery with excitement again. I suppose now's not the time to stop and admire though, we need to get the heck out of here.\n\nHop on my flying machine and help keep us covered from those iron dwarves on the way out!", objectives = "Accompany Brann Bronzebeard and his flying machine to Frosthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13418] = { id = 13418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations for War", description = "You there!\n\nYou look like you have some wits about you. We could use some more able bodies in Icecrown.\n\nYou may have heard rumors of our failure in assaulting the glacier from the ground, but let me set those concerns to rest. We're now mounting our assault from one of the most advanced pieces of engineering known to Azeroth, the Skybreaker. The Horde don't stand a chance, and neither does Arthas.\n\nSpeak to me when you're ready to depart.", completion = "Welcome to the Skybreaker.\n\nFrom here we are laying our groundwork for the assault on Arthas. There's a lot of work to be done, but before we can get into the real meat of it, we want to make sure that the Argent Crusade is adequately reinforced - we're going to need their help later.\n\nIf you have not already, speak to Absalan the Pious on the main deck.", objectives = "Speak to Officer Van Rossem to secure passage to the Skybreaker in Icecrown, and then report to High Captain Justin Bartlett.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13419] = { id = 13419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations for War", description = "You there!\n\nYou look like you have some wits about you. We could use some more able bodies in Icecrown.\n\nThe Alliance scum rushed into Icecrown ahead of us, unprepared, and got just what they deserved for their impatience. We took our time, we made ready, and soon we will mount a true assault from one of the most advanced pieces of engineering known to Azeroth - Orgrim's Hammer. The Alliance don't stand a chance, and neither does Arthas.\n\nSpeak to me when you're ready to depart and lend a hand.", completion = "Welcome to Orgrim's Hammer.\n\nFrom here we are laying our groundwork for the assault on Arthas. There's a lot of preparation to be done, but before we can get into the real meat of it, we want to make sure that the Argent Crusade is adequately reinforced - we're going to need their help later.\n\nIf you have not already, speak to Brother Keltan on the main deck.", objectives = "Speak to Sky-Reaver Klum to secure passage to Orgrim's Hammer in Icecrown, and then report to Sky-Reaver Korm Blackscar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13420] = { id = 13420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everfrost", description = "This piece of ice has been submitted to immense pressures and exposed to natural magics from deep beneath the world's surface. In combination, these effects have yielded an ice that will never melt.\n\nKnowing little of these things, you resolve to bring the sample back to Dun Niffelem. Someone there is bound to be familiar with its properties.", completion = "<The reflection of the everfrost sparkles in Calder's eye as he holds it aloft.>\n\nAhh, everfrost. The symbol of the heart of our people...\n\nEverfrost was once plentiful in this region. Over the ages, though, the jormungar have devoured nearly all of it. It is now very rare and very precious to my people.\n\nAs you roam these lands, keep a lookout for more pieces of everfrost. Return to me with any that you find and we will be most grateful.", objectives = "You are to return to Dun Niffelem and ask Calder about the piece of Everfrost.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13421] = { id = 13421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remember Everfrost!", progress = "Have you discovered any more everfrost, little {race}?", completion = "Well done, little {class}.\n\nEverfrost was once plentiful in this region. Over the ages, though, the jormungar devoured nearly all of it. It is now very rare and very precious to my people.\n\nAs you roam these lands, keep a lookout for more pieces of everfrost. Return to me with any that you find and we will be most grateful." }
quests[13422] = { id = 13422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maintaining Discipline", description = "You've succeeded where others have failed.  Yet you cannot rest on your laurels.\n\nYou must show others what strength and commitment really mean.\n\nThe male insubordinates inside the Forlorn Mine need to be disciplined once again.  Show them sister... show them what it means to disobey us.", completion = "You continue to lead by example.  We look up to you, sister.", objectives = "Gretta the Arbiter in Brunnhildar Village wants you to use the Disciplining Rod on 6 Exhausted Vrykul inside the Forlorn Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13423] = { id = 13423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending Your Title", description = "Everyone's impressed by your performance, sister.  But do not let your guard down -- every new challenger with delusions of grandeur is going to come out swinging for your title of Hyldskvinnar.\n\nShow these upstarts what you're made of.", completion = "You continue to prove yourself worthy.  We are honored by your presence.", objectives = "Gretta the Arbiter in Brunnhildar Village wants you to defeat 6 Victorious Challengers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13424] = { id = 13424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Pit", description = "To truly stay in your best riding shape you'll want to test yourself against the other Hyldnir every day.\n\nHead back into the Pit of the Fang and show them what you're capable of.  They'll appreciate suffering defeat to one as skilled as yourself.", progress = "Hail, sister.", completion = "You continue to demonstrate your prowess.  Your sisters have not lost their respect for you.", objectives = "Gretta the Arbiter, in Brunnhildar Village, wants you to use the Reins of the Icemaw Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13425] = { id = 13425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aberrations Must Die", description = "It is not enough to demonstrate your prowess among your peers.  You must also fight our enemies, dear sister.\n\nThe Valkyrion traitors continue to mock our noble drake-riding traditions by rearing plagued proto-drakes.\n\nSeize the frost oil they wield and use it to freeze their abominable plagued eggs.", completion = "A leader in more ways than one.  We thank you, sister.", objectives = "Gretta the Arbiter in Brunnhildar Village wants you to go to Valkyrion and obtain Vials of Frost Oil from the Valkyrion Aspirants. Use the Vials of Frost Oil to destroy 30 Plagued Proto-Drake Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13426] = { id = 13426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xarantaur, the Witness", description = "It seems we're not the only visitors to this area. A courier relayed a message from a tauren named Xarantaur, who said he was visiting a taunka village called Camp Tunka'lo. The note was somewhat cryptic, but it seems this Xarantaur has come to Storm Peaks to learn the history of a taunka legend.\n\nMeet up with him, {name}. See if what he knows can help us in any way. From his description, Camp Tunka'lo is far to the east, beyond the Terrace of the Makers and north of Dun Niffelem.", completion = "So Boktar received my note? That's excellent news. I doubted the taunka longrunner who carried it would reach anyone.", objectives = "Speak with Xarantaur at Camp Tunka'lo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13427] = { id = 13427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, {name}, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!", objectives = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13428] = { id = 13428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, {name}.  Earn great honor by heeding the call of the brave Frostwolf warriors.", objectives = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13429] = { id = 13429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Distraction for Akama", description = "<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>", progress = "<Xi'ri acknowledges your presence.>", completion = "<Xi'ri pulses with energy as you feel an object materialize in your hands.  It is the medallion you gave to A'dal on Akama's behalf, its power augmented by the naaru's magic.  The Sha'tar have entrusted you with the Medallion of Karabor, and with it access to the Black Temple.>", objectives = "Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi'ri's forces create a distraction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13430] = { id = 13430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Naaru: Magtheridon", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!", completion = "You have proven yourself as a being of great power. The naaru approve...", objectives = "A'dal in Shattrath City wants you to slay Magtheridon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13431] = { id = 13431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cudgel of Kar'desh", description = "Bring me the elemental signets that the cudgel requires!\n\nThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.\n\nThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.\n\nMake haste!", progress = "With the cudgel reformed, I shall break free of my bonds and return to Serpentshrine to exact vengeance on Vashj and her minions!", completion = "At last!\n\nWith these bonds broken and the cudgel in my possession I shall send  the sea witch back to the icy depths...", objectives = "Skar'this the Heretic in the heroic Slave Pens of Coilfang Reservoir wants you to bring him the Earthen Signet and the Blazing Signet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13432] = { id = 13432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vials of Eternity", description = "Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.\n\nWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.", progress = "I've asked the impossible of you, yet I expect you to succeed.  Much depends on it.", completion = "The power contained even in this small amount of water from the Well of Eternity is incredible.\n\nI can see clearly into every moment in time linked to Hyjal... the creation of the second Well of Eternity, Illidan's imprisonment, the enchantment of the World Tree and... yes!  The Battle of Mount Hyjal.\n\nWe must make haste, the timeline is not safe.", objectives = "Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13433] = { id = 13433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
